-- Work portfolio, generated by scripts/work-portfolio/build-sql.ts. Do not edit by hand.
-- 21 work items as DRAFTS, plus the agreed proof points.
BEGIN;

INSERT INTO public.proof_points (label, value, approved, pillars, sort_order, source_note)
SELECT 'countries', '36', true, ARRAY['ic', 'ex', 'ops']::text[], 10, 'South Pole, employees in 36 countries (2023 to 2026).'
WHERE NOT EXISTS (SELECT 1 FROM public.proof_points WHERE label = 'countries' AND value = '36');

INSERT INTO public.proof_points (label, value, approved, pillars, sort_order, source_note)
SELECT 'people supported', '~500', true, ARRAY['ex', 'ops', 'hrbp']::text[], 20, 'People supported across the employee lifecycle (agreed proof point, portfolio doc).'
WHERE NOT EXISTS (SELECT 1 FROM public.proof_points WHERE label = 'people supported' AND value = '~500');

INSERT INTO public.proof_points (label, value, approved, pillars, sort_order, source_note)
SELECT 'hires onboarded', '~300', true, ARRAY['ex']::text[], 30, 'New hires through the redesigned Buddy Programme, Oct 2022 to Mar 2023 onwards.'
WHERE NOT EXISTS (SELECT 1 FROM public.proof_points WHERE label = 'hires onboarded' AND value = '~300');

INSERT INTO public.proof_points (label, value, approved, pillars, sort_order, source_note)
SELECT 'live Town Hall attendance', '~60%', true, ARRAY['ic']::text[], 40, 'Real attendees against headcount per time zone (APAC, EMEA, Americas).'
WHERE NOT EXISTS (SELECT 1 FROM public.proof_points WHERE label = 'live Town Hall attendance' AND value = '~60%');

INSERT INTO public.proof_points (label, value, approved, pillars, sort_order, source_note)
SELECT 'intranet page views a year', '300K+', true, ARRAY['ic']::text[], 50, 'Internal newsroom on LumApps, measured.'
WHERE NOT EXISTS (SELECT 1 FROM public.proof_points WHERE label = 'intranet page views a year' AND value = '300K+');

INSERT INTO public.proof_points (label, value, approved, pillars, sort_order, source_note)
SELECT 'eNPS participation in 2025', '70%+', true, ARRAY['ex']::text[], 60, 'Every 2025 eNPS cycle, measured.'
WHERE NOT EXISTS (SELECT 1 FROM public.proof_points WHERE label = 'eNPS participation in 2025' AND value = '70%+');

-- 01 Town Halls people turned up for
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('town-halls',
  'case',
  'ic',
  'Town Halls people turned up for',
  'How Robert built monthly Town Halls for South Pole''s Certificates business line across three time zones, with live attendance around 60%.',
  '~60%',
  'live attendance',
  (SELECT id FROM public.proof_points WHERE label = 'live Town Hall attendance' AND value = '~60%' ORDER BY created_at LIMIT 1),
  'quote',
  'They became reliable and engaging, delivering real impact and not just updates.',
  'Real work, South Pole, 2024 to 2026',
  'Global People, Culture and Communications Specialist',
  '2024 to 2026',
  ARRAY['Town Halls', 'Leadership communication', 'Internal communications', 'Global teams']::text[],
  '/work/town-halls/cover.webp',
  'A long table in a dark meeting room, chairs set out and waiting for people to arrive.',
  '',
  true,
  '[{"id":"work-town-halls-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["A business line that heard about changes last"],"body":"<p>South Pole''s Certificates business line (then called Climate Projects) had people in three time zones and teams that mostly kept to themselves. Changes reached them late and second-hand, and Town Halls happened when the team could squeeze them in.</p><p>The cost landed on two groups: the people who found out about decisions after everyone else, and an operations team already stretched thin, who pulled each session together by hand.</p>"}},{"id":"work-town-halls-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["A monthly rhythm, built from scratch"],"steps":[{"title":"Took it on","description":"<p>Robert''s own brief was a different business line. He saw the gap in Certificates and offered to run its Town Halls on top of the day job.</p>"},{"title":"Set a monthly slot","description":"<p>One Town Hall a month in a fixed slot, so leaders could plan their updates and teams could plan their diaries.</p>"},{"title":"Followed the sun","description":"<p>On busy days he ran the same session three times, once each for APAC, EMEA and the Americas, so every region heard it live in working hours.</p>"},{"title":"Built one story","description":"<p>He collected updates from the line''s leaders ahead of each session and shaped them into one deck in Google Slides, with each speaker kept to time.</p>"},{"title":"Opened the floor","description":"<p>Questions came in through Google Forms, which gave quieter people a way in and gave leaders the hard questions in writing.</p>"},{"title":"Counted who came","description":"<p>He measured real attendees against headcount for each time zone. Live attendance held around 60%.</p>"}]}},{"id":"work-town-halls-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/town-halls/diagram.webp","alt_text":"Diagram in five steps: gather updates from leaders, build one deck in Google Slides, run the session for APAC, EMEA and the Americas, take questions in Google Forms, count attendees against headcount.","caption":"One month of Town Halls, from updates to attendance."}},{"id":"work-town-halls-4","type":"quote_band","strip_title":"Quote","bg_color":"","layout":{},"content":{"quote":"<p>Before Robert joined, the business line''s town halls happened when the team could squeeze them in. However, once he came on board, he built the structure behind them, and that changed everything. They became reliable and engaging, delivering real impact and not just updates. This took a lot off the operations team, who were already stretched thin.</p>","name":"Rachael Odhiambo","role":"Head of Operations - Certificates, South Pole","avatar":"/work/town-halls/rachael-odhiambo.webp","avatar_alt":"Portrait of Rachael Odhiambo","name_url":"https://www.linkedin.com/in/rachael-odhiambo-650a5a62/"}},{"id":"work-town-halls-5","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["From when-we-can to every month"],"body":"<p>Town Halls became a fixed part of the month. Live attendance held around 60% of headcount, measured per time zone, and the operations team got back the hours it used to spend pulling sessions together.</p><p>Alongside this, Robert supported the quarterly global CEO Town Halls and ghostwrote for the executive committee. The same updates ran in writing through the <a href=\"/work/internal-newsroom/\">internal newsroom</a>.</p>"}},{"id":"work-town-halls-6","type":"text","strip_title":"With hindsight","bg_color":"","layout":{},"content":{"eyebrow":"With hindsight","title_lines":["What he would add next time"],"body":"<p>More of the money. People want to know how the business is doing before they hear what it plans, so the financial picture earns a bigger slot.</p><p>And more sessions on more days and times, so people at the edges of a time zone get a live seat too.</p>"}},{"id":"work-town-halls-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How do you get people to attend a Town Hall live?","answer":"<p>Give it a fixed slot, run it once for each time zone and measure attendees against headcount per region. Here that held live attendance around 60%.</p>"},{"question":"Which tools ran these Town Halls?","answer":"<p>Google Meet for the session, Google Slides for the deck and Google Forms for questions.</p>"},{"question":"Who ran them?","answer":"<p>Robert-Marian Stănescu, founder of The Magic Coffin, while he was Global People, Culture and Communications Specialist at South Pole.</p>"}]}}]'::jsonb,
  '[{"id":"work-town-halls-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["A business line that heard about changes last"],"body":"<p>South Pole''s Certificates business line (then called Climate Projects) had people in three time zones and teams that mostly kept to themselves. Changes reached them late and second-hand, and Town Halls happened when the team could squeeze them in.</p><p>The cost landed on two groups: the people who found out about decisions after everyone else, and an operations team already stretched thin, who pulled each session together by hand.</p>"}},{"id":"work-town-halls-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["A monthly rhythm, built from scratch"],"steps":[{"title":"Took it on","description":"<p>Robert''s own brief was a different business line. He saw the gap in Certificates and offered to run its Town Halls on top of the day job.</p>"},{"title":"Set a monthly slot","description":"<p>One Town Hall a month in a fixed slot, so leaders could plan their updates and teams could plan their diaries.</p>"},{"title":"Followed the sun","description":"<p>On busy days he ran the same session three times, once each for APAC, EMEA and the Americas, so every region heard it live in working hours.</p>"},{"title":"Built one story","description":"<p>He collected updates from the line''s leaders ahead of each session and shaped them into one deck in Google Slides, with each speaker kept to time.</p>"},{"title":"Opened the floor","description":"<p>Questions came in through Google Forms, which gave quieter people a way in and gave leaders the hard questions in writing.</p>"},{"title":"Counted who came","description":"<p>He measured real attendees against headcount for each time zone. Live attendance held around 60%.</p>"}]}},{"id":"work-town-halls-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/town-halls/diagram.webp","alt_text":"Diagram in five steps: gather updates from leaders, build one deck in Google Slides, run the session for APAC, EMEA and the Americas, take questions in Google Forms, count attendees against headcount.","caption":"One month of Town Halls, from updates to attendance."}},{"id":"work-town-halls-4","type":"quote_band","strip_title":"Quote","bg_color":"","layout":{},"content":{"quote":"<p>Before Robert joined, the business line''s town halls happened when the team could squeeze them in. However, once he came on board, he built the structure behind them, and that changed everything. They became reliable and engaging, delivering real impact and not just updates. This took a lot off the operations team, who were already stretched thin.</p>","name":"Rachael Odhiambo","role":"Head of Operations - Certificates, South Pole","avatar":"/work/town-halls/rachael-odhiambo.webp","avatar_alt":"Portrait of Rachael Odhiambo","name_url":"https://www.linkedin.com/in/rachael-odhiambo-650a5a62/"}},{"id":"work-town-halls-5","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["From when-we-can to every month"],"body":"<p>Town Halls became a fixed part of the month. Live attendance held around 60% of headcount, measured per time zone, and the operations team got back the hours it used to spend pulling sessions together.</p><p>Alongside this, Robert supported the quarterly global CEO Town Halls and ghostwrote for the executive committee. The same updates ran in writing through the <a href=\"/work/internal-newsroom/\">internal newsroom</a>.</p>"}},{"id":"work-town-halls-6","type":"text","strip_title":"With hindsight","bg_color":"","layout":{},"content":{"eyebrow":"With hindsight","title_lines":["What he would add next time"],"body":"<p>More of the money. People want to know how the business is doing before they hear what it plans, so the financial picture earns a bigger slot.</p><p>And more sessions on more days and times, so people at the edges of a time zone get a live seat too.</p>"}},{"id":"work-town-halls-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How do you get people to attend a Town Hall live?","answer":"<p>Give it a fixed slot, run it once for each time zone and measure attendees against headcount per region. Here that held live attendance around 60%.</p>"},{"question":"Which tools ran these Town Halls?","answer":"<p>Google Meet for the session, Google Slides for the deck and Google Forms for questions.</p>"},{"question":"Who ran them?","answer":"<p>Robert-Marian Stănescu, founder of The Magic Coffin, while he was Global People, Culture and Communications Specialist at South Pole.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('live Town Hall attendance', '~60%'), ('countries', '36'))),
  true,
  10,
  'draft',
  'Town Halls with 60% live attendance: a case study',
  'How monthly Town Halls for a climate business line in 36 countries held around 60% live attendance, with one session for each time zone.',
  '/work/town-halls/og.jpg',
  'Case study. From 2024 to January 2026, Robert-Marian Stănescu (founder of The Magic Coffin) set up and ran monthly Town Halls for the Certificates business line at South Pole, a climate consultancy of 800 to 1,300 people in 36 countries. He took the work on himself, ran sessions for APAC, EMEA and the Americas on Google Meet with Google Slides and Google Forms, and measured live attendance at around 60% of headcount per time zone. He also supported the quarterly global CEO Town Halls and ghostwrote for the executive committee.')
ON CONFLICT (slug) DO UPDATE SET type = EXCLUDED.type, pillar = EXCLUDED.pillar, title = EXCLUDED.title, summary = EXCLUDED.summary, metric = EXCLUDED.metric, metric_label = EXCLUDED.metric_label, proof_point_id = EXCLUDED.proof_point_id, card_style = EXCLUDED.card_style, pull_line = EXCLUDED.pull_line, honesty_label = EXCLUDED.honesty_label, role_title = EXCLUDED.role_title, year = EXCLUDED.year, tags = EXCLUDED.tags, cover_image = EXCLUDED.cover_image, cover_image_alt = EXCLUDED.cover_image_alt, link_out = EXCLUDED.link_out, has_case_study = EXCLUDED.has_case_study, case_rows = EXCLUDED.case_rows, draft_case_rows = EXCLUDED.draft_case_rows, case_proof_ids = EXCLUDED.case_proof_ids, featured_home = EXCLUDED.featured_home, sort_order = EXCLUDED.sort_order, meta_title = EXCLUDED.meta_title, meta_description = EXCLUDED.meta_description, og_image = EXCLUDED.og_image, ai_summary = EXCLUDED.ai_summary, updated_at = now()
WHERE public.work_items.status = 'draft';

-- 02 An internal newsroom read 300K+ times a year
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('internal-newsroom',
  'case',
  'ic',
  'An internal newsroom read 300K+ times a year',
  'Four stories a month in articles, audio and video, for people in 36 countries, read more than 300,000 times a year.',
  '300K+',
  'page views a year',
  (SELECT id FROM public.proof_points WHERE label = 'intranet page views a year' AND value = '300K+' ORDER BY created_at LIMIT 1),
  'number',
  'Four stories a month, in the format people would finish.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Internal newsroom', 'Intranet', 'LumApps', 'Content']::text[],
  '/work/internal-newsroom/cover.webp',
  'A person in silhouette watching a wall of glowing screens.',
  '',
  true,
  '[{"id":"work-internal-newsroom-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["News that lived in inboxes and rumours"],"body":"<p>At a climate consultancy of 800 to 1,300 people in 36 countries, company news travelled by email, by team chat and by whoever happened to be in the room. People in smaller offices heard last.</p><p>The company needed one place where the news lived, written so people would want to read it.</p>"}},{"id":"work-internal-newsroom-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Ran it like a newsroom"],"steps":[{"title":"Set a pace","description":"<p>About four stories a month, around 50 a year, so people learned to check back.</p>"},{"title":"Kept a story list","description":"<p>He kept a running list fed by teams, leaders and the <a href=\"/work/town-halls/\">Town Halls</a>, and picked each month''s stories by who they affected most.</p>"},{"title":"Picked the format","description":"<p>Each story went out as an article, an audio piece or a video, chosen by what the story needed and how people would take it in.</p>"},{"title":"Published by audience","description":"<p>Stories went on the LumApps intranet and reached the people they were for through its audience targeting.</p>"},{"title":"Watched the reads","description":"<p>He tracked page views to see what people finished and fed that back into the next month''s list.</p>"}]}},{"id":"work-internal-newsroom-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/internal-newsroom/diagram.webp","alt_text":"Diagram in five steps: spot the story, pick article, audio or video, make it, publish it on LumApps by audience, check page views each month.","caption":"From story idea to measured reads."}},{"id":"work-internal-newsroom-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["One place for the news"],"body":"<p>The newsroom passed 300,000 page views a year, measured. For a company of 800 to 1,300 people, that is a lot of reading per person, and it gave leaders one channel they could count on.</p><p>It ran on the intranet Robert also helped <a href=\"/work/intranet-rebuild/\">rebuild</a>.</p>"}},{"id":"work-internal-newsroom-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How often should an internal newsroom publish?","answer":"<p>About once a week worked here: four stories a month, around 50 a year, as articles, audio and video.</p>"},{"question":"Which platform hosted it?","answer":"<p>The LumApps intranet.</p>"}]}}]'::jsonb,
  '[{"id":"work-internal-newsroom-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["News that lived in inboxes and rumours"],"body":"<p>At a climate consultancy of 800 to 1,300 people in 36 countries, company news travelled by email, by team chat and by whoever happened to be in the room. People in smaller offices heard last.</p><p>The company needed one place where the news lived, written so people would want to read it.</p>"}},{"id":"work-internal-newsroom-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Ran it like a newsroom"],"steps":[{"title":"Set a pace","description":"<p>About four stories a month, around 50 a year, so people learned to check back.</p>"},{"title":"Kept a story list","description":"<p>He kept a running list fed by teams, leaders and the <a href=\"/work/town-halls/\">Town Halls</a>, and picked each month''s stories by who they affected most.</p>"},{"title":"Picked the format","description":"<p>Each story went out as an article, an audio piece or a video, chosen by what the story needed and how people would take it in.</p>"},{"title":"Published by audience","description":"<p>Stories went on the LumApps intranet and reached the people they were for through its audience targeting.</p>"},{"title":"Watched the reads","description":"<p>He tracked page views to see what people finished and fed that back into the next month''s list.</p>"}]}},{"id":"work-internal-newsroom-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/internal-newsroom/diagram.webp","alt_text":"Diagram in five steps: spot the story, pick article, audio or video, make it, publish it on LumApps by audience, check page views each month.","caption":"From story idea to measured reads."}},{"id":"work-internal-newsroom-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["One place for the news"],"body":"<p>The newsroom passed 300,000 page views a year, measured. For a company of 800 to 1,300 people, that is a lot of reading per person, and it gave leaders one channel they could count on.</p><p>It ran on the intranet Robert also helped <a href=\"/work/intranet-rebuild/\">rebuild</a>.</p>"}},{"id":"work-internal-newsroom-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How often should an internal newsroom publish?","answer":"<p>About once a week worked here: four stories a month, around 50 a year, as articles, audio and video.</p>"},{"question":"Which platform hosted it?","answer":"<p>The LumApps intranet.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('intranet page views a year', '300K+'), ('countries', '36'))),
  true,
  20,
  'draft',
  'Internal newsroom with 300K+ views a year',
  'How an internal newsroom on LumApps published four stories a month in articles, audio and video, and passed 300,000 page views a year.',
  '/work/internal-newsroom/og.jpg',
  'Case study. At a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu ran an internal newsroom on the LumApps intranet: about four stories a month, around 50 a year, as articles, audio and video. The newsroom passed 300,000 page views a year, measured.')
ON CONFLICT (slug) DO UPDATE SET type = EXCLUDED.type, pillar = EXCLUDED.pillar, title = EXCLUDED.title, summary = EXCLUDED.summary, metric = EXCLUDED.metric, metric_label = EXCLUDED.metric_label, proof_point_id = EXCLUDED.proof_point_id, card_style = EXCLUDED.card_style, pull_line = EXCLUDED.pull_line, honesty_label = EXCLUDED.honesty_label, role_title = EXCLUDED.role_title, year = EXCLUDED.year, tags = EXCLUDED.tags, cover_image = EXCLUDED.cover_image, cover_image_alt = EXCLUDED.cover_image_alt, link_out = EXCLUDED.link_out, has_case_study = EXCLUDED.has_case_study, case_rows = EXCLUDED.case_rows, draft_case_rows = EXCLUDED.draft_case_rows, case_proof_ids = EXCLUDED.case_proof_ids, featured_home = EXCLUDED.featured_home, sort_order = EXCLUDED.sort_order, meta_title = EXCLUDED.meta_title, meta_description = EXCLUDED.meta_description, og_image = EXCLUDED.og_image, ai_summary = EXCLUDED.ai_summary, updated_at = now()
WHERE public.work_items.status = 'draft';

-- 03 Rebuilding a company intranet on LumApps
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('intranet-rebuild',
  'case',
  'ic',
  'Rebuilding a company intranet on LumApps',
  'A full intranet move: the migration, a new structure, landing pages, navigation, audience segments, training and an adoption campaign.',
  '',
  '',
  NULL,
  'photo',
  'A front door people could find their way through.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Intranet', 'LumApps', 'Information architecture', 'Adoption']::text[],
  '/work/intranet-rebuild/cover.webp',
  'Light split into a rainbow through a piece of glass.',
  '',
  true,
  '[{"id":"work-intranet-rebuild-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["An intranet that grew by accident"],"body":"<p>The old intranet had grown page by page. People searched, gave up and asked a colleague, which sent the same questions to the same few people every week.</p><p>The move to LumApps was the chance to rebuild the structure around how people look for things.</p>"}},{"id":"work-intranet-rebuild-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Structure first, then content"],"steps":[{"title":"Audited what existed","description":"<p>He listed the pages, owners and traffic, and sorted what to move, merge or retire.</p>"},{"title":"Drew the structure","description":"<p>He led the information architecture and the navigation, so each section had one clear home.</p>"},{"title":"Designed landing pages","description":"<p>He designed the landing pages people arrive on first, with segments so each audience saw what applied to them.</p>"},{"title":"Moved the content","description":"<p>He worked on the migration itself, page by page, with the owners of each section.</p>"},{"title":"Trained and launched","description":"<p>He trained people on the new intranet and ran an adoption campaign around the launch.</p>"},{"title":"Automated the org chart","description":"<p>He set up an org chart that updates itself from HiBob through Google. <a href=\"/work/org-chart-automation/\">How that chain works</a>.</p>"}]}},{"id":"work-intranet-rebuild-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/intranet-rebuild/diagram.webp","alt_text":"Diagram in five steps: audit the old intranet, draw the structure and navigation, design landing pages per audience, migrate content, launch with training and a campaign.","caption":"The rebuild, from audit to launch."}},{"id":"work-intranet-rebuild-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["One front door for the company"],"body":"<p>The company got one intranet with a structure people could learn, landing pages by audience and an org chart that keeps itself current. It became the home of the <a href=\"/work/internal-newsroom/\">internal newsroom</a>.</p>"}},{"id":"work-intranet-rebuild-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What does an intranet rebuild include?","answer":"<p>Here: the migration, information architecture, landing pages, navigation, audience segments, training, an adoption campaign and an automated org chart.</p>"},{"question":"Which platform was it?","answer":"<p>LumApps, with people data coming from HiBob through Google.</p>"}]}}]'::jsonb,
  '[{"id":"work-intranet-rebuild-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["An intranet that grew by accident"],"body":"<p>The old intranet had grown page by page. People searched, gave up and asked a colleague, which sent the same questions to the same few people every week.</p><p>The move to LumApps was the chance to rebuild the structure around how people look for things.</p>"}},{"id":"work-intranet-rebuild-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Structure first, then content"],"steps":[{"title":"Audited what existed","description":"<p>He listed the pages, owners and traffic, and sorted what to move, merge or retire.</p>"},{"title":"Drew the structure","description":"<p>He led the information architecture and the navigation, so each section had one clear home.</p>"},{"title":"Designed landing pages","description":"<p>He designed the landing pages people arrive on first, with segments so each audience saw what applied to them.</p>"},{"title":"Moved the content","description":"<p>He worked on the migration itself, page by page, with the owners of each section.</p>"},{"title":"Trained and launched","description":"<p>He trained people on the new intranet and ran an adoption campaign around the launch.</p>"},{"title":"Automated the org chart","description":"<p>He set up an org chart that updates itself from HiBob through Google. <a href=\"/work/org-chart-automation/\">How that chain works</a>.</p>"}]}},{"id":"work-intranet-rebuild-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/intranet-rebuild/diagram.webp","alt_text":"Diagram in five steps: audit the old intranet, draw the structure and navigation, design landing pages per audience, migrate content, launch with training and a campaign.","caption":"The rebuild, from audit to launch."}},{"id":"work-intranet-rebuild-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["One front door for the company"],"body":"<p>The company got one intranet with a structure people could learn, landing pages by audience and an org chart that keeps itself current. It became the home of the <a href=\"/work/internal-newsroom/\">internal newsroom</a>.</p>"}},{"id":"work-intranet-rebuild-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What does an intranet rebuild include?","answer":"<p>Here: the migration, information architecture, landing pages, navigation, audience segments, training, an adoption campaign and an automated org chart.</p>"},{"question":"Which platform was it?","answer":"<p>LumApps, with people data coming from HiBob through Google.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('countries', '36'))),
  false,
  30,
  'draft',
  'Rebuilding a company intranet on LumApps',
  'How a 36-country company moved to LumApps: migration, information architecture, landing pages, segments, training and an adoption campaign.',
  '/work/intranet-rebuild/og.jpg',
  'Case study. At a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu helped rebuild the company intranet on LumApps. He worked on the migration, the information architecture, landing pages, navigation and audience segmentation, trained people to use it, ran an adoption campaign and set up an org chart that updates itself from HiBob through Google.')
