-- 04 Recognition campaigns for an 18th birthday
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('recognition-campaign',
  'artefact',
  'ic',
  'Recognition campaigns for an 18th birthday',
  'Three LinkedIn campaigns that put employees at the front of a company''s 18th anniversary, with carousel graphics Robert designed.',
  '',
  '',
  NULL,
  'photo',
  'The birthday was about the people who got the company there.',
  'Real work, linked at the source',
  'Global People, Culture and Communications Specialist',
  '2024',
  ARRAY['Recognition', 'Employer brand', 'LinkedIn', 'Events']::text[],
  '/work/recognition-campaign/cover.webp',
  'A neon crown glowing orange and yellow on a dark wall.',
  'https://www.linkedin.com/posts/south-pole-global_south-pole-special-recognition-award-activity-7250434917644271616-sDdw/',
  true,
  '[{"id":"work-recognition-campaign-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Make the birthday about the people"],"body":"<p>A company turning 18 has a story to tell, and the best version of it is the people who built it. The anniversary needed something staff would see, share and be proud of.</p>"}},{"id":"work-recognition-campaign-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Three campaigns and a party in every office"],"steps":[{"title":"Conceived three campaigns","description":"<p>Three recognition campaigns for the company''s LinkedIn page, each putting named employees at the front.</p>"},{"title":"Designed the carousels","description":"<p>He designed the carousel graphics himself. The Special Recognition Award post is linked from this page.</p>"},{"title":"Ran the offices","description":"<p>He bought personalised merchandise, split the event budget across offices and worked with the workplace team in each location.</p>"},{"title":"Brought in the CEO","description":"<p>He lined up calls across time zones so the CEO could join each office''s celebration live, and ran in-office awards on the day.</p>"}]}},{"id":"work-recognition-campaign-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/recognition-campaign/diagram.webp","alt_text":"Diagram in five steps: pick the people, design carousel graphics, publish on the company LinkedIn page, celebrate in every office, bring the CEO in live across time zones.","caption":"The anniversary, online and in the offices."}},{"id":"work-recognition-campaign-4","type":"text","strip_title":"See it","bg_color":"","layout":{},"content":{"eyebrow":"See it","title_lines":["Linked, with the faces left where they belong"],"body":"<p>The campaign features colleagues by name and face, so this page links to the original post on LinkedIn instead of copying it here. The recognition habit carried on in a <a href=\"/work/recognition-platform/\">kudos tool Robert built later</a>.</p>"}},{"id":"work-recognition-campaign-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is an employee recognition campaign on LinkedIn?","answer":"<p>A series of posts on the company page that names and celebrates employees. Here there were three, for the company''s 18th anniversary.</p>"}]}}]'::jsonb,
  '[{"id":"work-recognition-campaign-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Make the birthday about the people"],"body":"<p>A company turning 18 has a story to tell, and the best version of it is the people who built it. The anniversary needed something staff would see, share and be proud of.</p>"}},{"id":"work-recognition-campaign-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Three campaigns and a party in every office"],"steps":[{"title":"Conceived three campaigns","description":"<p>Three recognition campaigns for the company''s LinkedIn page, each putting named employees at the front.</p>"},{"title":"Designed the carousels","description":"<p>He designed the carousel graphics himself. The Special Recognition Award post is linked from this page.</p>"},{"title":"Ran the offices","description":"<p>He bought personalised merchandise, split the event budget across offices and worked with the workplace team in each location.</p>"},{"title":"Brought in the CEO","description":"<p>He lined up calls across time zones so the CEO could join each office''s celebration live, and ran in-office awards on the day.</p>"}]}},{"id":"work-recognition-campaign-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/recognition-campaign/diagram.webp","alt_text":"Diagram in five steps: pick the people, design carousel graphics, publish on the company LinkedIn page, celebrate in every office, bring the CEO in live across time zones.","caption":"The anniversary, online and in the offices."}},{"id":"work-recognition-campaign-4","type":"text","strip_title":"See it","bg_color":"","layout":{},"content":{"eyebrow":"See it","title_lines":["Linked, with the faces left where they belong"],"body":"<p>The campaign features colleagues by name and face, so this page links to the original post on LinkedIn instead of copying it here. The recognition habit carried on in a <a href=\"/work/recognition-platform/\">kudos tool Robert built later</a>.</p>"}},{"id":"work-recognition-campaign-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is an employee recognition campaign on LinkedIn?","answer":"<p>A series of posts on the company page that names and celebrates employees. Here there were three, for the company''s 18th anniversary.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  40,
  'draft',
  'Employee recognition campaigns on LinkedIn',
  'Three LinkedIn campaigns that celebrated employees for a company''s 18th anniversary, with carousel graphics, plus the in-office celebrations.',
  '/work/recognition-campaign/og.jpg',
  'Artefact. For a climate company''s 18th anniversary, Robert-Marian Stănescu conceived and produced three employee recognition campaigns on the company''s LinkedIn page, with carousel graphics he designed, and ran the in-office celebrations across several offices with the CEO joining live across time zones.')
