-- 05 Turning policies into two-minute videos
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('policy-explainers',
  'artefact',
  'ic',
  'Turning policies into two-minute videos',
  'Robert scripted, shot and edited policy explainers until video became the standard. Here is a recreated sample.',
  '',
  '',
  NULL,
  'dark',
  'Two minutes of video beats ten pages of policy.',
  'Recreated with dummy data',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Video', 'Policy communication', 'Scriptwriting']::text[],
  '/work/policy-explainers/cover.webp',
  'Old television screens stacked into a triangle, glowing in the dark.',
  '',
  true,
  '[{"id":"work-policy-explainers-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Policies people would get to the end of"],"body":"<p>The company preferred video to long articles for policy news, because video is easier to take in. Robert turned that preference into a habit.</p>"}},{"id":"work-policy-explainers-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Script, shoot, cut"],"steps":[{"title":"Read the policy","description":"<p>He pulled out the three things a person needs: what it is, how to use it and where to ask.</p>"},{"title":"Wrote the script","description":"<p>Short lines, plain words, the reader''s question first.</p>"},{"title":"Checked it","description":"<p>The policy owner signed off the script before anything was filmed.</p>"},{"title":"Produced and edited","description":"<p>He produced and edited each video himself, including volunteering leave and time off.</p>"}]}},{"id":"work-policy-explainers-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/policy-explainers/diagram.webp","alt_text":"A sample video script in four timed parts for a fictional Recharge Days policy: the hook, what it is, how to book it and where to ask.","caption":"A recreated script for a fictional policy, Recharge Days."}},{"id":"work-policy-explainers-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Video became the standard"],"body":"<p>After the series, video became the company''s standard format for explaining a policy. The script above is a recreation with a fictional policy, so the real ones stay with the company.</p><p>The same plain-words habit runs through the <a href=\"/work/hard-announcement-kit/\">hard announcement kit</a> and the <a href=\"/work/intranet-rebuild/\">intranet rebuild</a>.</p>"}},{"id":"work-policy-explainers-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How long should a policy explainer video be?","answer":"<p>Around two minutes: what it is, how to use it and where to ask.</p>"},{"question":"Is the sample script real?","answer":"<p>It is recreated with dummy data, for a fictional policy.</p>"}]}}]'::jsonb,
  '[{"id":"work-policy-explainers-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Policies people would get to the end of"],"body":"<p>The company preferred video to long articles for policy news, because video is easier to take in. Robert turned that preference into a habit.</p>"}},{"id":"work-policy-explainers-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Script, shoot, cut"],"steps":[{"title":"Read the policy","description":"<p>He pulled out the three things a person needs: what it is, how to use it and where to ask.</p>"},{"title":"Wrote the script","description":"<p>Short lines, plain words, the reader''s question first.</p>"},{"title":"Checked it","description":"<p>The policy owner signed off the script before anything was filmed.</p>"},{"title":"Produced and edited","description":"<p>He produced and edited each video himself, including volunteering leave and time off.</p>"}]}},{"id":"work-policy-explainers-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/policy-explainers/diagram.webp","alt_text":"A sample video script in four timed parts for a fictional Recharge Days policy: the hook, what it is, how to book it and where to ask.","caption":"A recreated script for a fictional policy, Recharge Days."}},{"id":"work-policy-explainers-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Video became the standard"],"body":"<p>After the series, video became the company''s standard format for explaining a policy. The script above is a recreation with a fictional policy, so the real ones stay with the company.</p><p>The same plain-words habit runs through the <a href=\"/work/hard-announcement-kit/\">hard announcement kit</a> and the <a href=\"/work/intranet-rebuild/\">intranet rebuild</a>.</p>"}},{"id":"work-policy-explainers-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How long should a policy explainer video be?","answer":"<p>Around two minutes: what it is, how to use it and where to ask.</p>"},{"question":"Is the sample script real?","answer":"<p>It is recreated with dummy data, for a fictional policy.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  50,
  'draft',
  'Policy explainer videos: a recreated sample',
  'How policy explainer videos are scripted, produced and edited, with a recreated sample script for a fictional policy. Recreated with dummy data.',
  '/work/policy-explainers/og.jpg',
  'Artefact, recreated with dummy data. At a climate consultancy, Robert-Marian Stănescu scripted, produced and edited a series of policy explainer videos, including volunteering leave and time off, and video became the standard format for policy communication there. The sample on this page uses a fictional policy.')
