-- 06 A hard announcement kit, hour by hour
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('hard-announcement-kit',
  'playbook',
  'ic',
  'A hard announcement kit, hour by hour',
  'How we would plan a hard announcement at a fictional 200-person scale-up: the message house, the manager cascade, the FAQ and the timing.',
  '',
  '',
  NULL,
  'dark',
  'The people affected hear it first, from their own manager.',
  'Illustrative example, not client work',
  'The Magic Coffin playbook',
  '2026',
  ARRAY['Change communication', 'Manager cascade', 'Playbook']::text[],
  '/work/hard-announcement-kit/cover.webp',
  'People walking down a long dark corridor towards the light at the end.',
  '',
  true,
  '[{"id":"work-hard-announcement-kit-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A fictional scale-up with news to share"],"body":"<p>Lanternfish is a fictional 200-person scale-up. Its leaders have a decision to announce that changes some people''s jobs. The order people hear it in decides how much trust is left on Monday.</p>"}},{"id":"work-hard-announcement-kit-2","type":"process_steps","strip_title":"The kit","bg_color":"","layout":{},"content":{"eyebrow":"The kit","title_lines":["Four pieces, ready before anyone speaks"],"steps":[{"title":"Message house","description":"<p>One page with the core message, three supporting points and the facts behind each, so every leader says the same thing.</p>"},{"title":"Manager cascade","description":"<p>A briefing pack and a script for managers, with the likely questions and who answers what.</p>"},{"title":"FAQ","description":"<p>The questions people will ask in the first hour, answered in plain words, live when the all-hands ends.</p>"},{"title":"Timing plan","description":"<p>Hour by hour, so the people affected hear it first, from their own manager.</p>"}]}},{"id":"work-hard-announcement-kit-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/hard-announcement-kit/diagram.webp","alt_text":"Timeline in five steps: leadership aligned two days before, managers briefed the day before, people affected told by their manager at hour 0, everyone told in a live call with FAQ and email at hour 1, a note and pulse check two weeks on.","caption":"The timing plan, from two days before to two weeks after."}},{"id":"work-hard-announcement-kit-4","type":"text","strip_title":"How we would measure it","bg_color":"","layout":{},"content":{"eyebrow":"How we would measure it","title_lines":["Three signals in the first fortnight"],"body":"<p>Questions to managers in the first 48 hours, views of the FAQ and the result of the pulse check two weeks on. Team check-ins run through the first 48 hours.</p><p>This is how we run <a href=\"/services/internal-communications\">The Burial</a> and <a href=\"/services/internal-communications\">The Resurrection</a> when a hard moment is on the calendar. When the moment leans more HR than comms, <a href=\"/work/sample-vigil/\">The Vigil</a> covers the 72 hours around it.</p>"}},{"id":"work-hard-announcement-kit-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Who should hear a hard announcement first?","answer":"<p>Leadership two days before, managers the day before, then the people affected from their own manager, an hour before everyone else.</p>"},{"question":"What goes in a hard announcement kit?","answer":"<p>A message house, a manager cascade, an FAQ and an hour-by-hour timing plan.</p>"},{"question":"Is this a real company?","answer":"<p>Lanternfish is fictional. This is an illustrative example of how we would plan it.</p>"}]}}]'::jsonb,
  '[{"id":"work-hard-announcement-kit-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A fictional scale-up with news to share"],"body":"<p>Lanternfish is a fictional 200-person scale-up. Its leaders have a decision to announce that changes some people''s jobs. The order people hear it in decides how much trust is left on Monday.</p>"}},{"id":"work-hard-announcement-kit-2","type":"process_steps","strip_title":"The kit","bg_color":"","layout":{},"content":{"eyebrow":"The kit","title_lines":["Four pieces, ready before anyone speaks"],"steps":[{"title":"Message house","description":"<p>One page with the core message, three supporting points and the facts behind each, so every leader says the same thing.</p>"},{"title":"Manager cascade","description":"<p>A briefing pack and a script for managers, with the likely questions and who answers what.</p>"},{"title":"FAQ","description":"<p>The questions people will ask in the first hour, answered in plain words, live when the all-hands ends.</p>"},{"title":"Timing plan","description":"<p>Hour by hour, so the people affected hear it first, from their own manager.</p>"}]}},{"id":"work-hard-announcement-kit-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/hard-announcement-kit/diagram.webp","alt_text":"Timeline in five steps: leadership aligned two days before, managers briefed the day before, people affected told by their manager at hour 0, everyone told in a live call with FAQ and email at hour 1, a note and pulse check two weeks on.","caption":"The timing plan, from two days before to two weeks after."}},{"id":"work-hard-announcement-kit-4","type":"text","strip_title":"How we would measure it","bg_color":"","layout":{},"content":{"eyebrow":"How we would measure it","title_lines":["Three signals in the first fortnight"],"body":"<p>Questions to managers in the first 48 hours, views of the FAQ and the result of the pulse check two weeks on. Team check-ins run through the first 48 hours.</p><p>This is how we run <a href=\"/services/internal-communications\">The Burial</a> and <a href=\"/services/internal-communications\">The Resurrection</a> when a hard moment is on the calendar. When the moment leans more HR than comms, <a href=\"/work/sample-vigil/\">The Vigil</a> covers the 72 hours around it.</p>"}},{"id":"work-hard-announcement-kit-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Who should hear a hard announcement first?","answer":"<p>Leadership two days before, managers the day before, then the people affected from their own manager, an hour before everyone else.</p>"},{"question":"What goes in a hard announcement kit?","answer":"<p>A message house, a manager cascade, an FAQ and an hour-by-hour timing plan.</p>"},{"question":"Is this a real company?","answer":"<p>Lanternfish is fictional. This is an illustrative example of how we would plan it.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  60,
  'draft',
  'Hard announcement kit: a playbook',
  'A hard announcement plan for a fictional 200-person scale-up: message house, manager cascade, FAQ and an hour-by-hour timing plan.',
  '/work/hard-announcement-kit/og.jpg',
  'Playbook, illustrative example, not client work. How The Magic Coffin would plan a hard announcement at a fictional 200-person scale-up: a message house, a manager cascade, an FAQ and a timing plan that runs from leadership two days before to a pulse check two weeks after.')
