-- 07 A sample Autopsy: the internal comms audit
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('sample-autopsy',
  'playbook',
  'ic',
  'A sample Autopsy: the internal comms audit',
  'Inside our internal comms audit: interviews, a channel audit, the top vampire moments and a 30/60/90 roadmap.',
  '',
  '',
  NULL,
  'dark',
  'Lift the lid, name what''s draining people, fix it in 90 days.',
  'Illustrative example, not client work',
  'The Magic Coffin playbook',
  '2026',
  ARRAY['Internal comms audit', 'The Autopsy', 'Playbook']::text[],
  '/work/sample-autopsy/cover.webp',
  'A single beam of light falling into a bare concrete room.',
  '',
  true,
  '[{"id":"work-sample-autopsy-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["What you get when you book The Autopsy"],"body":"<p>Something is off: messages land flat and people know less about the company than its LinkedIn page does. The Autopsy finds where, in two to three weeks, from €900.</p>"}},{"id":"work-sample-autopsy-2","type":"process_steps","strip_title":"How we run it","bg_color":"","layout":{},"content":{"eyebrow":"How we run it","title_lines":["Four parts, one report"],"steps":[{"title":"Interviews","description":"<p>Conversations across three to five levels, so the report hears the new joiner as well as the leadership team.</p>"},{"title":"Channel audit","description":"<p>Every channel, who owns it, what it is for and where two channels say different things.</p>"},{"title":"Vampire moments","description":"<p>The handful of moments that drain trust, ranked by how many people they touch.</p>"},{"title":"30/60/90 roadmap","description":"<p>What to fix in the first month, what to build by the second and what to keep doing by the third.</p>"}]}},{"id":"work-sample-autopsy-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/sample-autopsy/diagram.webp","alt_text":"A sample report page with four sections: who we heard, channel audit, top vampire moments and a 30/60/90 day roadmap.","caption":"A sample page from an Autopsy report."}},{"id":"work-sample-autopsy-4","type":"text","strip_title":"What you keep","bg_color":"","layout":{},"content":{"eyebrow":"What you keep","title_lines":["A report your leadership team can act on"],"body":"<p>The full report runs 15 to 25 pages. The sample here is a four to six page excerpt. Many clients move straight on to <a href=\"/services/internal-communications\">The Burial</a>, the strategy and playbook.</p><p>Some of what we look for comes from running <a href=\"/work/town-halls/\">Town Halls</a> and a <a href=\"/work/internal-newsroom/\">newsroom</a> in-house.</p>"}},{"id":"work-sample-autopsy-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How long does an internal communications audit take?","answer":"<p>Two to three weeks, around 15 to 20 hours of your team''s time.</p>"},{"question":"How much does The Autopsy cost?","answer":"<p>From €900.</p>"},{"question":"What is a vampire moment?","answer":"<p>A moment in the working week that quietly drains trust or energy, such as news that reaches people second-hand.</p>"}]}}]'::jsonb,
  '[{"id":"work-sample-autopsy-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["What you get when you book The Autopsy"],"body":"<p>Something is off: messages land flat and people know less about the company than its LinkedIn page does. The Autopsy finds where, in two to three weeks, from €900.</p>"}},{"id":"work-sample-autopsy-2","type":"process_steps","strip_title":"How we run it","bg_color":"","layout":{},"content":{"eyebrow":"How we run it","title_lines":["Four parts, one report"],"steps":[{"title":"Interviews","description":"<p>Conversations across three to five levels, so the report hears the new joiner as well as the leadership team.</p>"},{"title":"Channel audit","description":"<p>Every channel, who owns it, what it is for and where two channels say different things.</p>"},{"title":"Vampire moments","description":"<p>The handful of moments that drain trust, ranked by how many people they touch.</p>"},{"title":"30/60/90 roadmap","description":"<p>What to fix in the first month, what to build by the second and what to keep doing by the third.</p>"}]}},{"id":"work-sample-autopsy-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/sample-autopsy/diagram.webp","alt_text":"A sample report page with four sections: who we heard, channel audit, top vampire moments and a 30/60/90 day roadmap.","caption":"A sample page from an Autopsy report."}},{"id":"work-sample-autopsy-4","type":"text","strip_title":"What you keep","bg_color":"","layout":{},"content":{"eyebrow":"What you keep","title_lines":["A report your leadership team can act on"],"body":"<p>The full report runs 15 to 25 pages. The sample here is a four to six page excerpt. Many clients move straight on to <a href=\"/services/internal-communications\">The Burial</a>, the strategy and playbook.</p><p>Some of what we look for comes from running <a href=\"/work/town-halls/\">Town Halls</a> and a <a href=\"/work/internal-newsroom/\">newsroom</a> in-house.</p>"}},{"id":"work-sample-autopsy-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How long does an internal communications audit take?","answer":"<p>Two to three weeks, around 15 to 20 hours of your team''s time.</p>"},{"question":"How much does The Autopsy cost?","answer":"<p>From €900.</p>"},{"question":"What is a vampire moment?","answer":"<p>A moment in the working week that quietly drains trust or energy, such as news that reaches people second-hand.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  70,
  'draft',
  'Sample internal comms audit (The Autopsy)',
  'See inside an internal communications audit: interviews, a channel audit, the moments that drain trust and a 30/60/90 roadmap. From €900.',
  '/work/sample-autopsy/og.jpg',
  'Playbook, illustrative example, not client work. The Autopsy is The Magic Coffin''s internal communications audit: interviews across three to five levels, a channel audit, the top vampire moments (where trust drains away) and a 30/60/90 day roadmap. From €900, two to three weeks. The sample is a four to six page excerpt of a 15 to 25 page report.')
