-- 08 Onboarding and a Buddy Programme for ~300 hires
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('onboarding-buddy-programme',
  'case',
  'ex',
  'Onboarding and a Buddy Programme for ~300 hires',
  'A global onboarding redesign: learning journeys in HowNow and an automated HiBob Buddy Programme for ~300 hires.',
  '~300',
  'hires onboarded',
  (SELECT id FROM public.proof_points WHERE label = 'hires onboarded' AND value = '~300' ORDER BY created_at LIMIT 1),
  'number',
  'Every new hire got a buddy, in every business unit, every time.',
  'Real work, anonymised',
  'Global People and Culture Trainee',
  '2022 to 2023',
  ARRAY['Onboarding', 'Buddy Programme', 'HiBob', 'HowNow']::text[],
  '/work/onboarding-buddy-programme/cover.webp',
  'A group of people in silhouette, backlit at the end of a hallway.',
  '',
  true,
  '[{"id":"work-onboarding-buddy-programme-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["A buddy system that ran on memory"],"body":"<p>Onboarding needed a full redesign. The Buddy Programme was a manual, bare-bones process, so whether a new hire got a buddy depended on someone remembering to set it up.</p><p>On top of that, a lot of people wanted a say in the new design.</p>"}},{"id":"work-onboarding-buddy-programme-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["One framework, many owners"],"steps":[{"title":"Took the brief","description":"<p>The redesign was assigned to Robert in his first role at the company, as a trainee.</p>"},{"title":"Built learning journeys","description":"<p>He set up role-specific onboarding journeys in HowNow LMS.</p>"},{"title":"Automated the buddy match","description":"<p>He built workflows in HiBob so every new hire got a buddy and the right prompts, without manual admin.</p>"},{"title":"Gave it a new name","description":"<p>He rebranded the Buddy Programme so people saw it as new, and set adoption targets for it, which it met.</p>"},{"title":"Shared the ownership","description":"<p>Each stakeholder owned their piece of the process, and Robert kept the overall framework. That settled the too-many-voices problem.</p>"}]}},{"id":"work-onboarding-buddy-programme-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/onboarding-buddy-programme/diagram.webp","alt_text":"Diagram in five steps: offer signed and HiBob starts the flow, buddy matched automatically, day one welcome and buddy intro, role-specific learning journey in HowNow, check-in with buddy and manager.","caption":"A new hire''s first weeks after the redesign."}},{"id":"work-onboarding-buddy-programme-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["The same welcome everywhere"],"body":"<p>Around 300 new hires went through the redesigned programme. The social integration workflow ran the same way in every business unit, every time, with no manual bottleneck.</p><p>We use the same thinking for a new manager''s <a href=\"/work/first-90-days/\">first 90 days</a>.</p>"}},{"id":"work-onboarding-buddy-programme-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How do you automate a buddy programme?","answer":"<p>Here, workflows in HiBob matched each new hire with a buddy and sent both of them prompts, so it ran without manual admin.</p>"},{"question":"How many people went through it?","answer":"<p>Around 300 new hires.</p>"}]}}]'::jsonb,
  '[{"id":"work-onboarding-buddy-programme-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["A buddy system that ran on memory"],"body":"<p>Onboarding needed a full redesign. The Buddy Programme was a manual, bare-bones process, so whether a new hire got a buddy depended on someone remembering to set it up.</p><p>On top of that, a lot of people wanted a say in the new design.</p>"}},{"id":"work-onboarding-buddy-programme-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["One framework, many owners"],"steps":[{"title":"Took the brief","description":"<p>The redesign was assigned to Robert in his first role at the company, as a trainee.</p>"},{"title":"Built learning journeys","description":"<p>He set up role-specific onboarding journeys in HowNow LMS.</p>"},{"title":"Automated the buddy match","description":"<p>He built workflows in HiBob so every new hire got a buddy and the right prompts, without manual admin.</p>"},{"title":"Gave it a new name","description":"<p>He rebranded the Buddy Programme so people saw it as new, and set adoption targets for it, which it met.</p>"},{"title":"Shared the ownership","description":"<p>Each stakeholder owned their piece of the process, and Robert kept the overall framework. That settled the too-many-voices problem.</p>"}]}},{"id":"work-onboarding-buddy-programme-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/onboarding-buddy-programme/diagram.webp","alt_text":"Diagram in five steps: offer signed and HiBob starts the flow, buddy matched automatically, day one welcome and buddy intro, role-specific learning journey in HowNow, check-in with buddy and manager.","caption":"A new hire''s first weeks after the redesign."}},{"id":"work-onboarding-buddy-programme-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["The same welcome everywhere"],"body":"<p>Around 300 new hires went through the redesigned programme. The social integration workflow ran the same way in every business unit, every time, with no manual bottleneck.</p><p>We use the same thinking for a new manager''s <a href=\"/work/first-90-days/\">first 90 days</a>.</p>"}},{"id":"work-onboarding-buddy-programme-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How do you automate a buddy programme?","answer":"<p>Here, workflows in HiBob matched each new hire with a buddy and sent both of them prompts, so it ran without manual admin.</p>"},{"question":"How many people went through it?","answer":"<p>Around 300 new hires.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('hires onboarded', '~300'), ('countries', '36'))),
  true,
  80,
  'draft',
  'Onboarding redesign for ~300 hires: a case study',
  'How a global onboarding redesign used HowNow learning journeys and an automated HiBob Buddy Programme for around 300 new hires.',
  '/work/onboarding-buddy-programme/og.jpg',
  'Case study. From October 2022 to March 2023, as Global People and Culture Trainee at a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu led the redesign of global onboarding: role-specific learning journeys in HowNow LMS and a renamed Buddy Programme with automated workflows in HiBob and adoption targets that were met. Around 300 new hires went through it, and the social integration workflow ran the same way in every business unit.')
