-- 09 An eNPS programme with 70%+ taking part
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('enps-programme',
  'case',
  'ex',
  'An eNPS programme with 70%+ taking part',
  'Robert designed and ran the company''s eNPS surveys and built the readouts for leadership. Participation stayed above 70% through 2025.',
  '70%+',
  'eNPS participation in 2025',
  (SELECT id FROM public.proof_points WHERE label = 'eNPS participation in 2025' AND value = '70%+' ORDER BY created_at LIMIT 1),
  'number',
  'A survey only earns the next response if people see what changed.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['eNPS', 'Engagement survey', 'Listening']::text[],
  '/work/enps-programme/cover.webp',
  'Glowing outlines of heads linked together in a network.',
  '',
  true,
  '[{"id":"work-enps-programme-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["Hearing a company that kept changing"],"body":"<p>At a climate consultancy of 800 to 1,300 people in 36 countries, leadership needed to know how people felt through a long stretch of change, and to act on it in a way people would notice.</p>"}},{"id":"work-enps-programme-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["From questions to team actions"],"steps":[{"title":"Designed the survey","description":"<p>He designed the eNPS surveys and set when each cycle ran.</p>"},{"title":"Ran each cycle","description":"<p>He administered every cycle, with reminders through the channels people read.</p>"},{"title":"Built the readout","description":"<p>The people analytics team ran the official analysis. Robert built the presentations and the takeaways.</p>"},{"title":"Took it to leadership","description":"<p>His manager presented the findings to the leadership team, and the two of them agreed with leadership how teams would act.</p>"},{"title":"Handed actions to teams","description":"<p>Each team owned its own action, in the way that suited its work.</p>"}]}},{"id":"work-enps-programme-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/enps-programme/diagram.webp","alt_text":"Diagram in five steps: design the survey, run it with reminders, analysis by the people analytics team, readout deck for leadership, each team owns its action.","caption":"One eNPS cycle, from design to team action."}},{"id":"work-enps-programme-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["People kept answering"],"body":"<p>Participation stayed above 70% through every 2025 cycle, measured, in a company in 36 countries. People answer again when they see their team act on the last round.</p><p>The listening sat beside a <a href=\"/work/recognition-platform/\">peer recognition tool</a> Robert built the same year.</p>"}},{"id":"work-enps-programme-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is a good eNPS participation rate?","answer":"<p>This programme held above 70% through 2025 across 36 countries.</p>"},{"question":"Who should own eNPS actions?","answer":"<p>Here each team owned its own action, agreed with leadership, which kept the changes close to the people who raised them.</p>"}]}}]'::jsonb,
  '[{"id":"work-enps-programme-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["Hearing a company that kept changing"],"body":"<p>At a climate consultancy of 800 to 1,300 people in 36 countries, leadership needed to know how people felt through a long stretch of change, and to act on it in a way people would notice.</p>"}},{"id":"work-enps-programme-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["From questions to team actions"],"steps":[{"title":"Designed the survey","description":"<p>He designed the eNPS surveys and set when each cycle ran.</p>"},{"title":"Ran each cycle","description":"<p>He administered every cycle, with reminders through the channels people read.</p>"},{"title":"Built the readout","description":"<p>The people analytics team ran the official analysis. Robert built the presentations and the takeaways.</p>"},{"title":"Took it to leadership","description":"<p>His manager presented the findings to the leadership team, and the two of them agreed with leadership how teams would act.</p>"},{"title":"Handed actions to teams","description":"<p>Each team owned its own action, in the way that suited its work.</p>"}]}},{"id":"work-enps-programme-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/enps-programme/diagram.webp","alt_text":"Diagram in five steps: design the survey, run it with reminders, analysis by the people analytics team, readout deck for leadership, each team owns its action.","caption":"One eNPS cycle, from design to team action."}},{"id":"work-enps-programme-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["People kept answering"],"body":"<p>Participation stayed above 70% through every 2025 cycle, measured, in a company in 36 countries. People answer again when they see their team act on the last round.</p><p>The listening sat beside a <a href=\"/work/recognition-platform/\">peer recognition tool</a> Robert built the same year.</p>"}},{"id":"work-enps-programme-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is a good eNPS participation rate?","answer":"<p>This programme held above 70% through 2025 across 36 countries.</p>"},{"question":"Who should own eNPS actions?","answer":"<p>Here each team owned its own action, agreed with leadership, which kept the changes close to the people who raised them.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('eNPS participation in 2025', '70%+'), ('countries', '36'))),
  false,
  90,
  'draft',
  'eNPS programme with 70%+ participation',
  'How an eNPS programme across 36 countries kept participation above 70% in 2025, and how each team took ownership of its own actions.',
  '/work/enps-programme/og.jpg',
  'Case study. At a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu designed and administered the eNPS surveys and built the presentations and takeaways. The people analytics team ran the official analysis, his manager presented the findings to leadership, and the two of them agreed with leadership that each team would own its own actions. Participation stayed above 70% through every 2025 cycle.')
