-- 10 A kudos platform built with Google Apps Script
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('recognition-platform',
  'case',
  'ex',
  'A kudos platform built with Google Apps Script',
  'A company-wide kudos tool built in Google Workspace: a form, a Chat broadcast, a note to the manager and the values.',
  '',
  '',
  NULL,
  'dark',
  'Thanks that reach the team, the manager and the review.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2025',
  ARRAY['Recognition', 'Google Apps Script', 'Gemini', 'Automation']::text[],
  '/work/recognition-platform/cover.webp',
  'A neon sign on a dark wall that reads better together.',
  '',
  true,
  '[{"id":"work-recognition-platform-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["Thanks that disappeared into a chat"],"body":"<p>The company had no tool for peer recognition. Thank-yous happened in passing and were gone by review season, so the people doing good work had little written evidence of it.</p>"}},{"id":"work-recognition-platform-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Built it in the tools people already had"],"steps":[{"title":"Pulled in people data","description":"<p>He linked a sheet of employee data so the form knew everyone and their manager.</p>"},{"title":"Made a kudos form","description":"<p>A short form: who, what they did and which company value it showed.</p>"},{"title":"Broadcast it","description":"<p>Each kudos went out in Google Chat with a reply thread, so colleagues could pile on.</p>"},{"title":"Told the manager","description":"<p>The manager got an email, so the thanks reached the person''s review.</p>"},{"title":"Mapped it to values","description":"<p>Every kudos was tagged with a company value, as evidence for performance reviews.</p>"},{"title":"Built it fast","description":"<p>He wrote it in Google Apps Script and used Gemini to speed up the build.</p>"}]}},{"id":"work-recognition-platform-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/recognition-platform/diagram.webp","alt_text":"Diagram in four steps: kudos form with who, what and which value; broadcast in Google Chat with replies; email to the manager; kudos mapped to company values in a sheet.","caption":"Where one kudos goes."}},{"id":"work-recognition-platform-4","type":"text","strip_title":"Where it got to","bg_color":"","layout":{},"content":{"eyebrow":"Where it got to","title_lines":["Built and shipped"],"body":"<p>The tool went live company-wide, built with the Google tools the company already paid for. Robert''s role ended before usage could be reviewed, so this page shows how it works and leaves the numbers out.</p><p>It followed the <a href=\"/work/recognition-campaign/\">anniversary recognition campaigns</a> and sat beside the <a href=\"/work/enps-programme/\">eNPS programme</a>.</p>"}},{"id":"work-recognition-platform-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Can you build a recognition tool in Google Workspace?","answer":"<p>Yes. This one used Google Apps Script, a form, Google Chat and email, with Gemini helping with the build.</p>"},{"question":"How many people used it?","answer":"<p>There is no usage figure: Robert''s role ended before usage was reviewed.</p>"}]}}]'::jsonb,
  '[{"id":"work-recognition-platform-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["Thanks that disappeared into a chat"],"body":"<p>The company had no tool for peer recognition. Thank-yous happened in passing and were gone by review season, so the people doing good work had little written evidence of it.</p>"}},{"id":"work-recognition-platform-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Built it in the tools people already had"],"steps":[{"title":"Pulled in people data","description":"<p>He linked a sheet of employee data so the form knew everyone and their manager.</p>"},{"title":"Made a kudos form","description":"<p>A short form: who, what they did and which company value it showed.</p>"},{"title":"Broadcast it","description":"<p>Each kudos went out in Google Chat with a reply thread, so colleagues could pile on.</p>"},{"title":"Told the manager","description":"<p>The manager got an email, so the thanks reached the person''s review.</p>"},{"title":"Mapped it to values","description":"<p>Every kudos was tagged with a company value, as evidence for performance reviews.</p>"},{"title":"Built it fast","description":"<p>He wrote it in Google Apps Script and used Gemini to speed up the build.</p>"}]}},{"id":"work-recognition-platform-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/recognition-platform/diagram.webp","alt_text":"Diagram in four steps: kudos form with who, what and which value; broadcast in Google Chat with replies; email to the manager; kudos mapped to company values in a sheet.","caption":"Where one kudos goes."}},{"id":"work-recognition-platform-4","type":"text","strip_title":"Where it got to","bg_color":"","layout":{},"content":{"eyebrow":"Where it got to","title_lines":["Built and shipped"],"body":"<p>The tool went live company-wide, built with the Google tools the company already paid for. Robert''s role ended before usage could be reviewed, so this page shows how it works and leaves the numbers out.</p><p>It followed the <a href=\"/work/recognition-campaign/\">anniversary recognition campaigns</a> and sat beside the <a href=\"/work/enps-programme/\">eNPS programme</a>.</p>"}},{"id":"work-recognition-platform-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Can you build a recognition tool in Google Workspace?","answer":"<p>Yes. This one used Google Apps Script, a form, Google Chat and email, with Gemini helping with the build.</p>"},{"question":"How many people used it?","answer":"<p>There is no usage figure: Robert''s role ended before usage was reviewed.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  100,
  'draft',
  'Peer recognition tool in Google Apps Script',
  'How a company-wide kudos tool was built in Google Apps Script, Chat and Workspace with Gemini, and mapped each kudos to the company values.',
  '/work/recognition-platform/og.jpg',
  'Case study. In 2025, at a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu built a peer recognition platform from scratch in Google Apps Script, Google Chat and Google Workspace, using Gemini to speed up the build. A kudos form fed a Google Chat broadcast with reply threads, emailed the person''s manager and mapped each kudos to a company value for performance reviews.')
