VALUES ('work-for-the-world',
  'artefact',
  'ex',
  'Work for the World: an employer brand campaign',
  'Robert came up with the Work for the World concept, led the design, wrote the careers page copy and edited every video.',
  '',
  '',
  NULL,
  'photo',
  'A careers page that says what the work is for.',
  'Real work, linked at the source',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Employer brand', 'Careers page', 'Video']::text[],
  '/work/work-for-the-world/cover.webp',
  'Hands planting a seedling in dark soil.',
  'https://careers.southpole.com/',
  true,
  '[{"id":"work-work-for-the-world-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Tell candidates what the work is for"],"body":"<p>A climate company hires people who want their job to count. The careers page needed to say that plainly and show it.</p>"}},{"id":"work-work-for-the-world-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Concept, design, words and edit"],"steps":[{"title":"Came up with the concept","description":"<p>Work for the World started as Robert''s idea.</p>"},{"title":"Led the design","description":"<p>He led the design behind the campaign and the careers page.</p>"},{"title":"Wrote the page","description":"<p>He wrote the careers page content.</p>"},{"title":"Edited every video","description":"<p>He edited all the campaign videos himself.</p>"}]}},{"id":"work-work-for-the-world-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/work-for-the-world/diagram.webp","alt_text":"Diagram in five steps: the Work for the World concept, design, careers page copy, video editing, the live careers page.","caption":"The campaign, from idea to the live careers page."}},{"id":"work-work-for-the-world-4","type":"text","strip_title":"See it","bg_color":"","layout":{},"content":{"eyebrow":"See it","title_lines":["Still live"],"body":"<p>The careers page was still live in August 2026, and this page links to it. Candidates who join through a page like this meet the <a href=\"/work/onboarding-buddy-programme/\">onboarding</a> next.</p>"}},{"id":"work-work-for-the-world-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Who made Work for the World?","answer":"<p>Robert-Marian Stănescu came up with the concept, led the design, wrote the careers page content and edited all the videos.</p>"}]}}]'::jsonb,
  '[{"id":"work-work-for-the-world-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Tell candidates what the work is for"],"body":"<p>A climate company hires people who want their job to count. The careers page needed to say that plainly and show it.</p>"}},{"id":"work-work-for-the-world-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Concept, design, words and edit"],"steps":[{"title":"Came up with the concept","description":"<p>Work for the World started as Robert''s idea.</p>"},{"title":"Led the design","description":"<p>He led the design behind the campaign and the careers page.</p>"},{"title":"Wrote the page","description":"<p>He wrote the careers page content.</p>"},{"title":"Edited every video","description":"<p>He edited all the campaign videos himself.</p>"}]}},{"id":"work-work-for-the-world-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/work-for-the-world/diagram.webp","alt_text":"Diagram in five steps: the Work for the World concept, design, careers page copy, video editing, the live careers page.","caption":"The campaign, from idea to the live careers page."}},{"id":"work-work-for-the-world-4","type":"text","strip_title":"See it","bg_color":"","layout":{},"content":{"eyebrow":"See it","title_lines":["Still live"],"body":"<p>The careers page was still live in August 2026, and this page links to it. Candidates who join through a page like this meet the <a href=\"/work/onboarding-buddy-programme/\">onboarding</a> next.</p>"}},{"id":"work-work-for-the-world-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Who made Work for the World?","answer":"<p>Robert-Marian Stănescu came up with the concept, led the design, wrote the careers page content and edited all the videos.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  110,
  'draft',
  'Work for the World employer brand campaign',
  'The Work for the World employer brand campaign: concept, design lead, careers page copy and every video edit, still live in 2026.',
  '/work/work-for-the-world/og.jpg',
  'Artefact. Robert-Marian Stănescu came up with the Work for the World employer brand campaign for a climate consultancy, led the design behind it and the careers page content, and edited all the campaign videos. The careers page was still live in August 2026.')
