-- 12 A self-service tier for employee questions
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('self-service-tier',
  'case',
  'ops',
  'A self-service tier for employee questions',
  'Tier 0 of a tiered query system in Jira for Legal, IT and Risk, and People and Culture, so routine answers reached people first.',
  '',
  '',
  NULL,
  'photo',
  'The answer first, the person when you need one.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Self-service', 'Jira', 'HR service delivery', 'Tiered support']::text[],
  '/work/self-service-tier/cover.webp',
  'Beams of light falling through the roof of a large warehouse.',
  '',
  true,
  '[{"id":"work-self-service-tier-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["The same questions, asked one by one"],"body":"<p>Employee questions to Legal, IT and Risk, and People and Culture arrived one at a time and landed on the same few people. Routine questions waited in line behind hard ones.</p>"}},{"id":"work-self-service-tier-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Built the layer before the people"],"steps":[{"title":"Mapped the questions","description":"<p>He grouped the questions people asked most, by team.</p>"},{"title":"Wrote the answers","description":"<p>He built self-service resources for the routine ones.</p>"},{"title":"Set up Tier 0 in Jira","description":"<p>He designed and ran Tier 0, so people saw an answer before a ticket reached a person.</p>"},{"title":"Routed the rest","description":"<p>Anything Tier 0 could answer went no further. Everything else reached the right team in Jira.</p>"},{"title":"Kept it current","description":"<p>New questions from tickets became new Tier 0 answers.</p>"}]}},{"id":"work-self-service-tier-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/self-service-tier/diagram.webp","alt_text":"Diagram in five steps: an employee asks a question, Tier 0 offers a self-service answer, Tier 1 routes it to the right team in Jira, Tier 2 goes to a specialist, and feedback turns new questions into Tier 0 answers.","caption":"How a question moves through the tiers."}},{"id":"work-self-service-tier-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Answers first, company-wide"],"body":"<p>Tier 0 ran company-wide across 36 countries, for three teams at once. The teams felt the load drop. The drop went unmeasured, so this page leaves the percentage out.</p><p>This is the tiered self-service system we build in <a href=\"/services/people-operations\">The Reanimation</a>.</p>"}},{"id":"work-self-service-tier-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is Tier 0 in HR service delivery?","answer":"<p>The self-service layer: answers people find themselves before a question becomes a ticket for a person.</p>"},{"question":"Which teams did it cover?","answer":"<p>Legal, IT and Risk, and People and Culture, in Jira.</p>"}]}}]'::jsonb,
  '[{"id":"work-self-service-tier-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["The same questions, asked one by one"],"body":"<p>Employee questions to Legal, IT and Risk, and People and Culture arrived one at a time and landed on the same few people. Routine questions waited in line behind hard ones.</p>"}},{"id":"work-self-service-tier-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Built the layer before the people"],"steps":[{"title":"Mapped the questions","description":"<p>He grouped the questions people asked most, by team.</p>"},{"title":"Wrote the answers","description":"<p>He built self-service resources for the routine ones.</p>"},{"title":"Set up Tier 0 in Jira","description":"<p>He designed and ran Tier 0, so people saw an answer before a ticket reached a person.</p>"},{"title":"Routed the rest","description":"<p>Anything Tier 0 could answer went no further. Everything else reached the right team in Jira.</p>"},{"title":"Kept it current","description":"<p>New questions from tickets became new Tier 0 answers.</p>"}]}},{"id":"work-self-service-tier-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/self-service-tier/diagram.webp","alt_text":"Diagram in five steps: an employee asks a question, Tier 0 offers a self-service answer, Tier 1 routes it to the right team in Jira, Tier 2 goes to a specialist, and feedback turns new questions into Tier 0 answers.","caption":"How a question moves through the tiers."}},{"id":"work-self-service-tier-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Answers first, company-wide"],"body":"<p>Tier 0 ran company-wide across 36 countries, for three teams at once. The teams felt the load drop. The drop went unmeasured, so this page leaves the percentage out.</p><p>This is the tiered self-service system we build in <a href=\"/services/people-operations\">The Reanimation</a>.</p>"}},{"id":"work-self-service-tier-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is Tier 0 in HR service delivery?","answer":"<p>The self-service layer: answers people find themselves before a question becomes a ticket for a person.</p>"},{"question":"Which teams did it cover?","answer":"<p>Legal, IT and Risk, and People and Culture, in Jira.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('countries', '36'))),
  true,
  120,
  'draft',
  'Self-service HR help desk tier in Jira',
  'How a Tier 0 self-service layer in Jira answered routine questions for Legal, IT and Risk, and People and Culture across 36 countries.',
  '/work/self-service-tier/og.jpg',
  'Case study. At a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu designed and ran Tier 0 of a tiered employee query system in Jira, covering Legal, IT and Risk, and People and Culture, with self-service answers for routine questions before they reached a person. It ran company-wide. No deflection figure was measured.')
