-- 13 Mandatory training across 36 countries
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('mandatory-training',
  'case',
  'ops',
  'Mandatory training across 36 countries',
  'Recurring HowNow modules on phishing, data protection, KYC, GDPR and inclusion, with completion and accuracy tracked everywhere.',
  '',
  '',
  NULL,
  'photo',
  'Training that comes round on time, for everyone.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Compliance training', 'HowNow', 'LMS', 'Inclusion']::text[],
  '/work/mandatory-training/cover.webp',
  'Rows of fluorescent light tubes across a dark ceiling.',
  '',
  true,
  '[{"id":"work-mandatory-training-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["Rules that had to reach everyone, every year"],"body":"<p>A company in 36 countries has to show that everyone knows how to spot a phishing email and handle personal data. The training had to come round on time and the records had to stand up.</p>"}},{"id":"work-mandatory-training-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Recurring, tracked and built or bought"],"steps":[{"title":"Built the modules","description":"<p>He built and switched on recurring modules in HowNow LMS: phishing, data protection, KYC and GDPR.</p>"},{"title":"Assigned by audience","description":"<p>Each module went to the people it applied to, on a repeating schedule.</p>"},{"title":"Tracked two numbers","description":"<p>He tracked completion and accuracy, so the company knew who had done it and who had understood it.</p>"},{"title":"Added inclusion training","description":"<p>After specific leadership incidents, he set up harassment and inclusive-language training. He wrote some of it, outsourced some and licensed some from OpenSesame.</p>"}]}},{"id":"work-mandatory-training-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/mandatory-training/diagram.webp","alt_text":"Diagram in five steps: build the module in HowNow, assign it by role and country, send reminders before the deadline, track completion and accuracy, repeat next cycle.","caption":"One mandatory training cycle."}},{"id":"work-mandatory-training-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["A programme that runs itself each year"],"body":"<p>Mandatory training became a recurring programme, tracked in every country. The same build-or-buy judgement shows up in the <a href=\"/work/support-onboarding-curriculum/\">support onboarding curriculum</a>.</p>"}},{"id":"work-mandatory-training-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Should you build or buy compliance training?","answer":"<p>Both can work. Here some inclusion training was written in-house, some outsourced and some licensed from OpenSesame.</p>"},{"question":"What should you track for mandatory training?","answer":"<p>Completion and accuracy: who finished it and who understood it.</p>"}]}}]'::jsonb,
  '[{"id":"work-mandatory-training-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["Rules that had to reach everyone, every year"],"body":"<p>A company in 36 countries has to show that everyone knows how to spot a phishing email and handle personal data. The training had to come round on time and the records had to stand up.</p>"}},{"id":"work-mandatory-training-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Recurring, tracked and built or bought"],"steps":[{"title":"Built the modules","description":"<p>He built and switched on recurring modules in HowNow LMS: phishing, data protection, KYC and GDPR.</p>"},{"title":"Assigned by audience","description":"<p>Each module went to the people it applied to, on a repeating schedule.</p>"},{"title":"Tracked two numbers","description":"<p>He tracked completion and accuracy, so the company knew who had done it and who had understood it.</p>"},{"title":"Added inclusion training","description":"<p>After specific leadership incidents, he set up harassment and inclusive-language training. He wrote some of it, outsourced some and licensed some from OpenSesame.</p>"}]}},{"id":"work-mandatory-training-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/mandatory-training/diagram.webp","alt_text":"Diagram in five steps: build the module in HowNow, assign it by role and country, send reminders before the deadline, track completion and accuracy, repeat next cycle.","caption":"One mandatory training cycle."}},{"id":"work-mandatory-training-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["A programme that runs itself each year"],"body":"<p>Mandatory training became a recurring programme, tracked in every country. The same build-or-buy judgement shows up in the <a href=\"/work/support-onboarding-curriculum/\">support onboarding curriculum</a>.</p>"}},{"id":"work-mandatory-training-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Should you build or buy compliance training?","answer":"<p>Both can work. Here some inclusion training was written in-house, some outsourced and some licensed from OpenSesame.</p>"},{"question":"What should you track for mandatory training?","answer":"<p>Completion and accuracy: who finished it and who understood it.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('countries', '36'))),
  false,
  130,
  'draft',
  'Mandatory compliance training in HowNow',
  'How recurring compliance training in HowNow covered phishing, data protection, KYC, GDPR and inclusion, with completion tracked in 36 countries.',
  '/work/mandatory-training/og.jpg',
  'Case study. At a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu built and switched on recurring mandatory training modules in HowNow LMS on phishing, data protection, KYC and GDPR, plus inclusion modules, and tracked completion and accuracy rates. Some inclusion training was written in-house, some outsourced and some licensed from OpenSesame.')
