-- 14 An org chart that keeps itself up to date
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('org-chart-automation',
  'case',
  'ops',
  'An org chart that keeps itself up to date',
  'A chain from HiBob to Google to LumApps, so the intranet org chart updates when the HR system does.',
  '',
  '',
  NULL,
  'photo',
  'Change it once in HR, see it everywhere.',
  'Real work, anonymised',
  'Global People, Culture and Communications Specialist',
  '2023 to 2026',
  ARRAY['Org chart', 'HiBob', 'LumApps', 'Automation']::text[],
  '/work/org-chart-automation/cover.webp',
  'A blue and white grid of building panels, repeating into the distance.',
  '',
  true,
  '[{"id":"work-org-chart-automation-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["An org chart out of date by Monday"],"body":"<p>The new intranet needed an org chart people could trust. Kept by hand, it would be wrong after the next joiner, leaver or reorg.</p>"}},{"id":"work-org-chart-automation-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["One source, two hops"],"steps":[{"title":"Picked the source","description":"<p>HiBob, the HR system, stayed the single place where reporting lines are changed.</p>"},{"title":"Sent it to Google","description":"<p>People data flowed from HiBob into the company''s Google directory.</p>"},{"title":"Read it in LumApps","description":"<p>LumApps built the org chart from Google, so the intranet showed the same lines as HR.</p>"},{"title":"Tested the edges","description":"<p>He checked joiners, leavers and manager changes all the way through.</p>"}]}},{"id":"work-org-chart-automation-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/org-chart-automation/diagram.webp","alt_text":"Diagram in three steps: HiBob as the source of truth, Google directory sync, the org chart on the LumApps intranet.","caption":"From HiBob, through Google, to the LumApps org chart."}},{"id":"work-org-chart-automation-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Change it once"],"body":"<p>The org chart on the intranet updates itself when HR changes a record. It was part of the <a href=\"/work/intranet-rebuild/\">intranet rebuild</a>.</p>"}},{"id":"work-org-chart-automation-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Can HiBob feed a LumApps org chart?","answer":"<p>Here it ran through Google: HiBob to Google, then Google to LumApps.</p>"}]}}]'::jsonb,
  '[{"id":"work-org-chart-automation-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["An org chart out of date by Monday"],"body":"<p>The new intranet needed an org chart people could trust. Kept by hand, it would be wrong after the next joiner, leaver or reorg.</p>"}},{"id":"work-org-chart-automation-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["One source, two hops"],"steps":[{"title":"Picked the source","description":"<p>HiBob, the HR system, stayed the single place where reporting lines are changed.</p>"},{"title":"Sent it to Google","description":"<p>People data flowed from HiBob into the company''s Google directory.</p>"},{"title":"Read it in LumApps","description":"<p>LumApps built the org chart from Google, so the intranet showed the same lines as HR.</p>"},{"title":"Tested the edges","description":"<p>He checked joiners, leavers and manager changes all the way through.</p>"}]}},{"id":"work-org-chart-automation-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/org-chart-automation/diagram.webp","alt_text":"Diagram in three steps: HiBob as the source of truth, Google directory sync, the org chart on the LumApps intranet.","caption":"From HiBob, through Google, to the LumApps org chart."}},{"id":"work-org-chart-automation-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Change it once"],"body":"<p>The org chart on the intranet updates itself when HR changes a record. It was part of the <a href=\"/work/intranet-rebuild/\">intranet rebuild</a>.</p>"}},{"id":"work-org-chart-automation-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"Can HiBob feed a LumApps org chart?","answer":"<p>Here it ran through Google: HiBob to Google, then Google to LumApps.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('countries', '36'))),
  false,
  140,
  'draft',
  'Automated org chart: HiBob to Google to LumApps',
  'How an intranet org chart stays current by itself: people data flows from HiBob to Google and on to LumApps, company-wide.',
  '/work/org-chart-automation/og.jpg',
  'Case study. At a climate consultancy of 800 to 1,300 people in 36 countries, Robert-Marian Stănescu set up an integration chain from HiBob to Google and from Google to LumApps, so the org chart on the intranet updates itself from the HR system. It ran company-wide as part of the LumApps rollout.')
