-- 15 A HiBob workflow: promotion to pay rise, on time
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('sample-hibob-workflow',
  'artefact',
  'ops',
  'A HiBob workflow: promotion to pay rise, on time',
  'A recreated workflow that takes a promotion from the manager''s request to the right pay in the right payroll run.',
  '',
  '',
  NULL,
  'dark',
  'A promotion should show up in the payslip the month it starts.',
  'Recreated with dummy data',
  'The Magic Coffin sample',
  '2026',
  ARRAY['HiBob', 'Workflow', 'Promotions', 'Payroll']::text[],
  '/work/sample-hibob-workflow/cover.webp',
  'A glass staircase lit up at night.',
  '',
  true,
  '[{"id":"work-sample-hibob-workflow-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A promotion that reaches the payslip"],"body":"<p>A manager promotes someone in March. The pay rise should land in March too. In many scale-ups it lands in May, after three emails and a reminder.</p><p>Robert spent years in HiBob and checked HiBob against payroll every month, so this sample is built from what he saw go wrong.</p>"}},{"id":"work-sample-hibob-workflow-2","type":"process_steps","strip_title":"The workflow","bg_color":"","layout":{},"content":{"eyebrow":"The workflow","title_lines":["Six steps, each with an owner"],"steps":[{"title":"Request","description":"<p>The manager fills in one form: new title, new pay, start date.</p>"},{"title":"Approve","description":"<p>The people partner and the department leader approve in HiBob.</p>"},{"title":"Check the budget","description":"<p>Finance confirms the money is in the budget.</p>"},{"title":"Change the record","description":"<p>HiBob records the new title and pay with the right effective date.</p>"},{"title":"Pay it","description":"<p>The change goes into the payroll export before the cut-off.</p>"},{"title":"Tell the person","description":"<p>The employee gets the letter on the day it starts.</p>"}]}},{"id":"work-sample-hibob-workflow-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/sample-hibob-workflow/diagram.webp","alt_text":"Workflow in six steps: manager request, approval by the people partner and leader, finance budget check, dated pay change in HiBob, payroll export before cut-off, letter to the employee.","caption":"A recreated promotion workflow, with dummy data."}},{"id":"work-sample-hibob-workflow-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["Part of The Reanimation"],"body":"<p>This is the kind of system we build in <a href=\"/services/people-operations\">The Reanimation</a>, next to a <a href=\"/work/self-service-tier/\">self-service tier</a> for the questions people ask.</p>"}},{"id":"work-sample-hibob-workflow-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How do you make sure a promotion is paid on time?","answer":"<p>Give every step an owner and a date, record the change in HiBob with the effective date, and export it before the payroll cut-off.</p>"},{"question":"Is this real client data?","answer":"<p>It is recreated with dummy data.</p>"}]}}]'::jsonb,
  '[{"id":"work-sample-hibob-workflow-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A promotion that reaches the payslip"],"body":"<p>A manager promotes someone in March. The pay rise should land in March too. In many scale-ups it lands in May, after three emails and a reminder.</p><p>Robert spent years in HiBob and checked HiBob against payroll every month, so this sample is built from what he saw go wrong.</p>"}},{"id":"work-sample-hibob-workflow-2","type":"process_steps","strip_title":"The workflow","bg_color":"","layout":{},"content":{"eyebrow":"The workflow","title_lines":["Six steps, each with an owner"],"steps":[{"title":"Request","description":"<p>The manager fills in one form: new title, new pay, start date.</p>"},{"title":"Approve","description":"<p>The people partner and the department leader approve in HiBob.</p>"},{"title":"Check the budget","description":"<p>Finance confirms the money is in the budget.</p>"},{"title":"Change the record","description":"<p>HiBob records the new title and pay with the right effective date.</p>"},{"title":"Pay it","description":"<p>The change goes into the payroll export before the cut-off.</p>"},{"title":"Tell the person","description":"<p>The employee gets the letter on the day it starts.</p>"}]}},{"id":"work-sample-hibob-workflow-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/sample-hibob-workflow/diagram.webp","alt_text":"Workflow in six steps: manager request, approval by the people partner and leader, finance budget check, dated pay change in HiBob, payroll export before cut-off, letter to the employee.","caption":"A recreated promotion workflow, with dummy data."}},{"id":"work-sample-hibob-workflow-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["Part of The Reanimation"],"body":"<p>This is the kind of system we build in <a href=\"/services/people-operations\">The Reanimation</a>, next to a <a href=\"/work/self-service-tier/\">self-service tier</a> for the questions people ask.</p>"}},{"id":"work-sample-hibob-workflow-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How do you make sure a promotion is paid on time?","answer":"<p>Give every step an owner and a date, record the change in HiBob with the effective date, and export it before the payroll cut-off.</p>"},{"question":"Is this real client data?","answer":"<p>It is recreated with dummy data.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  150,
  'draft',
  'Sample HiBob promotion workflow',
  'A recreated HiBob workflow that takes a promotion from request to approval to the right pay in the right payroll run. Dummy data.',
  '/work/sample-hibob-workflow/og.jpg',
  'Artefact, recreated with dummy data. A HiBob workflow that takes a promotion from a manager''s request through approval and budget checks to a dated compensation change, the payroll export and the letter to the employee. It shows the kind of system The Magic Coffin builds in The Reanimation.')
