-- 16 A sample Vigil: 72 hours around a hard moment
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('sample-vigil',
  'playbook',
  'hrbp',
  'A sample Vigil: 72 hours around a hard moment',
  'How we would support a fictional 200-person scale-up through one hard moment, hour by hour, as a fractional HR business partner.',
  '',
  '',
  NULL,
  'dark',
  'Someone who has done this before, in the room for three days.',
  'Illustrative example, not client work',
  'The Magic Coffin playbook',
  '2026',
  ARRAY['Fractional HRBP', 'The Vigil', 'Employee relations', 'Playbook']::text[],
  '/work/sample-vigil/cover.webp',
  'A single chair under a spotlight in an empty dark room.',
  '',
  true,
  '[{"id":"work-sample-vigil-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["Lanternfish has a hard week ahead"],"body":"<p>Lanternfish, a fictional 200-person scale-up, has no HR business partner. A team is being restructured and the founders want it done well, and quickly.</p>"}},{"id":"work-sample-vigil-2","type":"process_steps","strip_title":"How we would run it","bg_color":"","layout":{},"content":{"eyebrow":"How we would run it","title_lines":["Three days, one moment"],"steps":[{"title":"Hours 0 to 8","description":"<p>Get the facts, spot the legal and people risks, and agree one plan with the founders.</p>"},{"title":"Hours 8 to 24","description":"<p>Brief leaders and managers, write the scripts and prepare the <a href=\"/work/hard-announcement-kit/\">announcement kit</a>.</p>"},{"title":"Day two","description":"<p>Sit in on the hard conversations, support managers between them and answer questions as they come.</p>"},{"title":"Day three","description":"<p>Follow up with the people affected, close the records and check in with the team that stays.</p>"},{"title":"Afterwards","description":"<p>A handover note: what happened, what is still open and who owns it.</p>"}]}},{"id":"work-sample-vigil-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/sample-vigil/diagram.webp","alt_text":"Timeline in five steps: facts, risks and plan in hours 0 to 8; leaders and managers ready by hour 24; the conversations on day two; follow-up and records on day three; a handover note afterwards.","caption":"The 72 hours of a Vigil, from facts to handover."}},{"id":"work-sample-vigil-4","type":"text","strip_title":"Where it comes from","bg_color":"","layout":{},"content":{"eyebrow":"Where it comes from","title_lines":["Built on years of hard moments"],"body":"<p>Robert supported around 500 people across the employee lifecycle in-house before starting The Magic Coffin. <a href=\"/services/fractional-hrbp\">The Vigil</a> is from €500 a day, with a three-day minimum.</p><p>Managers who want to get ahead of the moment can start with the <a href=\"/work/manager-conversation-guide/\">conversation guide</a>.</p>"}},{"id":"work-sample-vigil-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is The Vigil?","answer":"<p>Single hard-moment support from a fractional HR business partner: one defined moment, handled end to end.</p>"},{"question":"How much does The Vigil cost?","answer":"<p>From €500 a day, with a three-day minimum.</p>"},{"question":"Is Lanternfish a real company?","answer":"<p>It is fictional. This is an illustrative example.</p>"}]}}]'::jsonb,
  '[{"id":"work-sample-vigil-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["Lanternfish has a hard week ahead"],"body":"<p>Lanternfish, a fictional 200-person scale-up, has no HR business partner. A team is being restructured and the founders want it done well, and quickly.</p>"}},{"id":"work-sample-vigil-2","type":"process_steps","strip_title":"How we would run it","bg_color":"","layout":{},"content":{"eyebrow":"How we would run it","title_lines":["Three days, one moment"],"steps":[{"title":"Hours 0 to 8","description":"<p>Get the facts, spot the legal and people risks, and agree one plan with the founders.</p>"},{"title":"Hours 8 to 24","description":"<p>Brief leaders and managers, write the scripts and prepare the <a href=\"/work/hard-announcement-kit/\">announcement kit</a>.</p>"},{"title":"Day two","description":"<p>Sit in on the hard conversations, support managers between them and answer questions as they come.</p>"},{"title":"Day three","description":"<p>Follow up with the people affected, close the records and check in with the team that stays.</p>"},{"title":"Afterwards","description":"<p>A handover note: what happened, what is still open and who owns it.</p>"}]}},{"id":"work-sample-vigil-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/sample-vigil/diagram.webp","alt_text":"Timeline in five steps: facts, risks and plan in hours 0 to 8; leaders and managers ready by hour 24; the conversations on day two; follow-up and records on day three; a handover note afterwards.","caption":"The 72 hours of a Vigil, from facts to handover."}},{"id":"work-sample-vigil-4","type":"text","strip_title":"Where it comes from","bg_color":"","layout":{},"content":{"eyebrow":"Where it comes from","title_lines":["Built on years of hard moments"],"body":"<p>Robert supported around 500 people across the employee lifecycle in-house before starting The Magic Coffin. <a href=\"/services/fractional-hrbp\">The Vigil</a> is from €500 a day, with a three-day minimum.</p><p>Managers who want to get ahead of the moment can start with the <a href=\"/work/manager-conversation-guide/\">conversation guide</a>.</p>"}},{"id":"work-sample-vigil-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What is The Vigil?","answer":"<p>Single hard-moment support from a fractional HR business partner: one defined moment, handled end to end.</p>"},{"question":"How much does The Vigil cost?","answer":"<p>From €500 a day, with a three-day minimum.</p>"},{"question":"Is Lanternfish a real company?","answer":"<p>It is fictional. This is an illustrative example.</p>"}]}}]'::jsonb,
  ARRAY(SELECT id FROM public.proof_points WHERE (label, value) IN (('people supported', '~500'))),
  true,
  160,
  'draft',
  'Sample Vigil: 72 hours of HRBP support',
  'How a fractional HR business partner would support a fictional 200-person scale-up through one hard moment in 72 hours. From €500 a day.',
  '/work/sample-vigil/og.jpg',
  'Playbook, illustrative example, not client work. The Vigil is The Magic Coffin''s single hard-moment support from a fractional HR business partner: one defined moment (a restructure, a difficult exit, a policy crisis) handled end to end. This sample follows a fictional 200-person scale-up through 72 hours. From €500 a day, with a three-day minimum.')
