-- 17 The conversation before someone resigns
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('manager-conversation-guide',
  'playbook',
  'hrbp',
  'The conversation before someone resigns',
  'A guide for managers on the talk to have when a good person seems ready to leave: what to ask, what to listen for and what to offer.',
  '',
  '',
  NULL,
  'dark',
  'Ask before the letter arrives.',
  'Illustrative example, not client work. Not legal advice',
  'The Magic Coffin playbook',
  '2026',
  ARRAY['Retention', 'Managers', 'Stay conversation', 'Playbook']::text[],
  '/work/manager-conversation-guide/cover.webp',
  'A dark meeting room with light coming in through one window.',
  '',
  true,
  '[{"id":"work-manager-conversation-guide-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A good person has gone quiet"],"body":"<p>Their camera is off more. They stopped arguing in meetings. A manager who asks now has a chance; a manager who waits gets a letter.</p>"}},{"id":"work-manager-conversation-guide-2","type":"process_steps","strip_title":"The guide","bg_color":"","layout":{},"content":{"eyebrow":"The guide","title_lines":["Open, ask, listen, follow up"],"steps":[{"title":"Open plainly","description":"<p>Say why you asked for the time: you want to hear how work is going for them.</p>"},{"title":"Ask two questions","description":"<p>What would make you stay another year? What would you change tomorrow?</p>"},{"title":"Listen for the reason","description":"<p>Workload, growth, pay, your own management or life outside work. Each needs a different answer.</p>"},{"title":"Offer what you can","description":"<p>Only what you can deliver. Check pay and role questions with HR before promising anything.</p>"},{"title":"Follow up","description":"<p>Write it down, agree one next step and come back within two weeks.</p>"}]}},{"id":"work-manager-conversation-guide-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/manager-conversation-guide/diagram.webp","alt_text":"A one-page guide in four parts: how to open the conversation, two questions to ask, what to listen for, and what to do after.","caption":"The guide on one page."}},{"id":"work-manager-conversation-guide-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["Part of fractional HRBP support"],"body":"<p>We coach managers through these talks in the <a href=\"/services/fractional-hrbp\">Fractional HRBP</a> retainer. New managers get it early in their <a href=\"/work/first-90-days/\">first 90 days</a>. This guide is general and is not legal advice.</p>"}},{"id":"work-manager-conversation-guide-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What should a manager ask when someone might resign?","answer":"<p>What would make you stay another year, and what would you change tomorrow.</p>"},{"question":"Is this legal advice?","answer":"<p>No. It is a general guide; check anything about pay, contracts or notice with HR or a lawyer.</p>"}]}}]'::jsonb,
  '[{"id":"work-manager-conversation-guide-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A good person has gone quiet"],"body":"<p>Their camera is off more. They stopped arguing in meetings. A manager who asks now has a chance; a manager who waits gets a letter.</p>"}},{"id":"work-manager-conversation-guide-2","type":"process_steps","strip_title":"The guide","bg_color":"","layout":{},"content":{"eyebrow":"The guide","title_lines":["Open, ask, listen, follow up"],"steps":[{"title":"Open plainly","description":"<p>Say why you asked for the time: you want to hear how work is going for them.</p>"},{"title":"Ask two questions","description":"<p>What would make you stay another year? What would you change tomorrow?</p>"},{"title":"Listen for the reason","description":"<p>Workload, growth, pay, your own management or life outside work. Each needs a different answer.</p>"},{"title":"Offer what you can","description":"<p>Only what you can deliver. Check pay and role questions with HR before promising anything.</p>"},{"title":"Follow up","description":"<p>Write it down, agree one next step and come back within two weeks.</p>"}]}},{"id":"work-manager-conversation-guide-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/manager-conversation-guide/diagram.webp","alt_text":"A one-page guide in four parts: how to open the conversation, two questions to ask, what to listen for, and what to do after.","caption":"The guide on one page."}},{"id":"work-manager-conversation-guide-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["Part of fractional HRBP support"],"body":"<p>We coach managers through these talks in the <a href=\"/services/fractional-hrbp\">Fractional HRBP</a> retainer. New managers get it early in their <a href=\"/work/first-90-days/\">first 90 days</a>. This guide is general and is not legal advice.</p>"}},{"id":"work-manager-conversation-guide-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What should a manager ask when someone might resign?","answer":"<p>What would make you stay another year, and what would you change tomorrow.</p>"},{"question":"Is this legal advice?","answer":"<p>No. It is a general guide; check anything about pay, contracts or notice with HR or a lawyer.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  170,
  'draft',
  'Manager guide: the talk before a resignation',
  'A manager''s guide to the conversation before someone resigns: what to ask, what to listen for and what you can offer. Not legal advice.',
  '/work/manager-conversation-guide/og.jpg',
  'Playbook, illustrative example, not client work, not legal advice. A guide for managers on the conversation to have when a good person seems ready to leave: how to open it, the questions to ask, what to listen for, what to offer and what to write down afterwards.')
