-- 18 A pay transparency readiness check
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('pay-readiness-check',
  'playbook',
  'pay',
  'A pay transparency readiness check',
  'A fictional Stockholm scale-up checked against the EU Pay Transparency Directive, with a red, amber and green summary.',
  '',
  '',
  NULL,
  'dark',
  'Know where you stand before the rules arrive.',
  'Illustrative example, not client work. Not legal advice',
  'The Magic Coffin playbook',
  '2026',
  ARRAY['Pay transparency', 'EU directive', 'The Autopsy', 'Playbook']::text[],
  '/work/pay-readiness-check/cover.webp',
  'An hourglass with sand running through, on a dark background.',
  '',
  true,
  '[{"id":"work-pay-readiness-check-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A Stockholm scale-up with a deadline"],"body":"<p>Kvarnby Software is a fictional 120-person SaaS scale-up in Stockholm. Its founders know the EU Pay Transparency Directive is coming and want to know how far they have to go.</p>"}},{"id":"work-pay-readiness-check-2","type":"process_steps","strip_title":"What we check","bg_color":"","layout":{},"content":{"eyebrow":"What we check","title_lines":["Four checks, one summary"],"steps":[{"title":"Job ads","description":"<p>Do the ads or the first interview give a pay range?</p>"},{"title":"Pay history","description":"<p>Does anyone still ask candidates what they earn now?</p>"},{"title":"Criteria","description":"<p>Are pay and progression set on gender-neutral criteria: skills, effort, responsibility and working conditions?</p>"},{"title":"Pay requests","description":"<p>Can people ask about pay levels, and does someone own the answer?</p>"}]}},{"id":"work-pay-readiness-check-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/pay-readiness-check/diagram.webp","alt_text":"A traffic-light table for a fictional company: pay ranges in job ads red, pay history questions amber, gender-neutral criteria amber, asking about pay levels green.","caption":"A sample red, amber and green summary for a fictional company."}},{"id":"work-pay-readiness-check-4","type":"text","strip_title":"What you get","bg_color":"","layout":{},"content":{"eyebrow":"What you get","title_lines":["A summary and three fixes"],"body":"<p>A red, amber and green summary, and the three fixes that move the most red to green. <a href=\"/services/pay-transparency\">The Autopsy for pay transparency</a> runs from €750, over one to two weeks and about 12 to 15 hours.</p><p>Directive dates and national rules are checked on the day each report goes out. This sample is general and is not legal advice. Next comes explaining the bands to staff: see the <a href=\"/work/pay-range-explainer/\">pay-range explainer</a>.</p>"}},{"id":"work-pay-readiness-check-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What does a pay transparency readiness check cover?","answer":"<p>Pay ranges in job ads, pay history questions, gender-neutral pay criteria and how people can ask about pay levels.</p>"},{"question":"How long does it take?","answer":"<p>One to two weeks, about 12 to 15 hours, from €750.</p>"},{"question":"Is this legal advice?","answer":"<p>No. It is a general sample; dates and national rules are checked on the day each report is issued.</p>"}]}}]'::jsonb,
  '[{"id":"work-pay-readiness-check-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["A Stockholm scale-up with a deadline"],"body":"<p>Kvarnby Software is a fictional 120-person SaaS scale-up in Stockholm. Its founders know the EU Pay Transparency Directive is coming and want to know how far they have to go.</p>"}},{"id":"work-pay-readiness-check-2","type":"process_steps","strip_title":"What we check","bg_color":"","layout":{},"content":{"eyebrow":"What we check","title_lines":["Four checks, one summary"],"steps":[{"title":"Job ads","description":"<p>Do the ads or the first interview give a pay range?</p>"},{"title":"Pay history","description":"<p>Does anyone still ask candidates what they earn now?</p>"},{"title":"Criteria","description":"<p>Are pay and progression set on gender-neutral criteria: skills, effort, responsibility and working conditions?</p>"},{"title":"Pay requests","description":"<p>Can people ask about pay levels, and does someone own the answer?</p>"}]}},{"id":"work-pay-readiness-check-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/pay-readiness-check/diagram.webp","alt_text":"A traffic-light table for a fictional company: pay ranges in job ads red, pay history questions amber, gender-neutral criteria amber, asking about pay levels green.","caption":"A sample red, amber and green summary for a fictional company."}},{"id":"work-pay-readiness-check-4","type":"text","strip_title":"What you get","bg_color":"","layout":{},"content":{"eyebrow":"What you get","title_lines":["A summary and three fixes"],"body":"<p>A red, amber and green summary, and the three fixes that move the most red to green. <a href=\"/services/pay-transparency\">The Autopsy for pay transparency</a> runs from €750, over one to two weeks and about 12 to 15 hours.</p><p>Directive dates and national rules are checked on the day each report goes out. This sample is general and is not legal advice. Next comes explaining the bands to staff: see the <a href=\"/work/pay-range-explainer/\">pay-range explainer</a>.</p>"}},{"id":"work-pay-readiness-check-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What does a pay transparency readiness check cover?","answer":"<p>Pay ranges in job ads, pay history questions, gender-neutral pay criteria and how people can ask about pay levels.</p>"},{"question":"How long does it take?","answer":"<p>One to two weeks, about 12 to 15 hours, from €750.</p>"},{"question":"Is this legal advice?","answer":"<p>No. It is a general sample; dates and national rules are checked on the day each report is issued.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  true,
  180,
  'draft',
  'Pay transparency readiness check: a sample',
  'A sample EU Pay Transparency Directive check for a fictional Stockholm scale-up: job ads, pay history, criteria and pay requests. Not legal advice.',
  '/work/pay-readiness-check/og.jpg',
  'Playbook, illustrative example, not client work, not legal advice. The Magic Coffin''s Pay Transparency Check (The Autopsy) on a fictional 120-person Stockholm SaaS scale-up: it checks pay ranges in job ads, pay history questions, gender-neutral pay criteria and how people can ask about pay levels, and ends with a red, amber and green summary and three fixes. From €750, one to two weeks, about 12 to 15 hours.')
