-- 19 A pay-range explainer staff can read in five minutes
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('pay-range-explainer',
  'artefact',
  'pay',
  'A pay-range explainer staff can read in five minutes',
  'A recreated one-page explainer with dummy bands, plus the manager FAQ that goes with it.',
  '',
  '',
  NULL,
  'dark',
  'A pay band is finished when people can explain their own.',
  'Recreated with dummy data. Not legal advice',
  'The Magic Coffin sample',
  '2026',
  ARRAY['Pay transparency', 'Pay bands', 'The Reckoning']::text[],
  '/work/pay-range-explainer/cover.webp',
  'A glass prism splitting white light into a band of colour.',
  '',
  true,
  '[{"id":"work-pay-range-explainer-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Bands people understand"],"body":"<p>A pay structure works once people understand it. The explainer is the page staff read; the FAQ is what their manager says when they ask why.</p>"}},{"id":"work-pay-range-explainer-2","type":"process_steps","strip_title":"What is in it","bg_color":"","layout":{},"content":{"eyebrow":"What is in it","title_lines":["One page and one FAQ"],"steps":[{"title":"Your level","description":"<p>What a level is and what sets it.</p>"},{"title":"Your band","description":"<p>The range for each level, shown with dummy numbers here.</p>"},{"title":"Moving up","description":"<p>How pay moves inside a band and between levels.</p>"},{"title":"How to ask","description":"<p>How to ask about pay levels, who answers and by when.</p>"},{"title":"Manager FAQ","description":"<p>Ten questions managers get after the explainer goes out, with plain answers.</p>"}]}},{"id":"work-pay-range-explainer-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/pay-range-explainer/diagram.webp","alt_text":"A one-page pay explainer in four parts: your level, your band with dummy figures, moving up, and how to ask about pay levels.","caption":"A recreated one-page explainer with dummy bands."}},{"id":"work-pay-range-explainer-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["Part of The Reckoning"],"body":"<p>We write this in <a href=\"/services/pay-transparency\">The Reckoning</a>, from €1,400, after the <a href=\"/work/pay-readiness-check/\">readiness check</a> and the bands are set. All figures here are dummy data, and the sample is general and is not legal advice.</p>"}},{"id":"work-pay-range-explainer-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What should a pay-range explainer include?","answer":"<p>What a level is, the band for each level, how pay moves and how to ask about pay levels.</p>"},{"question":"Are these real pay bands?","answer":"<p>No. They are dummy data for the sample.</p>"}]}}]'::jsonb,
  '[{"id":"work-pay-range-explainer-1","type":"text","strip_title":"The brief","bg_color":"","layout":{},"content":{"eyebrow":"The brief","title_lines":["Bands people understand"],"body":"<p>A pay structure works once people understand it. The explainer is the page staff read; the FAQ is what their manager says when they ask why.</p>"}},{"id":"work-pay-range-explainer-2","type":"process_steps","strip_title":"What is in it","bg_color":"","layout":{},"content":{"eyebrow":"What is in it","title_lines":["One page and one FAQ"],"steps":[{"title":"Your level","description":"<p>What a level is and what sets it.</p>"},{"title":"Your band","description":"<p>The range for each level, shown with dummy numbers here.</p>"},{"title":"Moving up","description":"<p>How pay moves inside a band and between levels.</p>"},{"title":"How to ask","description":"<p>How to ask about pay levels, who answers and by when.</p>"},{"title":"Manager FAQ","description":"<p>Ten questions managers get after the explainer goes out, with plain answers.</p>"}]}},{"id":"work-pay-range-explainer-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/pay-range-explainer/diagram.webp","alt_text":"A one-page pay explainer in four parts: your level, your band with dummy figures, moving up, and how to ask about pay levels.","caption":"A recreated one-page explainer with dummy bands."}},{"id":"work-pay-range-explainer-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["Part of The Reckoning"],"body":"<p>We write this in <a href=\"/services/pay-transparency\">The Reckoning</a>, from €1,400, after the <a href=\"/work/pay-readiness-check/\">readiness check</a> and the bands are set. All figures here are dummy data, and the sample is general and is not legal advice.</p>"}},{"id":"work-pay-range-explainer-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What should a pay-range explainer include?","answer":"<p>What a level is, the band for each level, how pay moves and how to ask about pay levels.</p>"},{"question":"Are these real pay bands?","answer":"<p>No. They are dummy data for the sample.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  190,
  'draft',
  'Pay-range explainer for staff: a sample',
  'A one-page pay-range explainer and manager FAQ, with dummy pay bands, so staff know how pay works. Recreated sample, not legal advice.',
  '/work/pay-range-explainer/og.jpg',
  'Artefact, recreated with dummy data, not legal advice. A one-page explainer that tells staff how pay ranges work, with dummy bands, plus a manager FAQ for the questions that follow. It is the kind of material The Magic Coffin writes in The Reckoning, from €1,400.')
