-- 20 A new manager's first 90 days
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('first-90-days',
  'playbook',
  'mgr',
  'A new manager''s first 90 days',
  'A 90-day plan for someone managing people for the first time: weeks one and two, three to six, and seven to twelve.',
  '',
  '',
  NULL,
  'dark',
  'Managers are made. Ninety days gets you most of the way.',
  'Illustrative example, not client work',
  'The Magic Coffin playbook',
  '2026',
  ARRAY['New managers', 'The Grimoire', 'The Night School', 'Playbook']::text[],
  '/work/first-90-days/cover.webp',
  'A person shining a torch beam up into the Milky Way at night.',
  '',
  true,
  '[{"id":"work-first-90-days-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["Promoted on Friday, managing on Monday"],"body":"<p>Most new managers are promoted for being good at the job they just left. The first 90 days decide whether the team gets a manager or a very busy colleague.</p>"}},{"id":"work-first-90-days-2","type":"process_steps","strip_title":"The plan","bg_color":"","layout":{},"content":{"eyebrow":"The plan","title_lines":["Three stages"],"steps":[{"title":"Weeks 1 and 2: listen","description":"<p>A one-to-one with everyone, the same five questions each time, and a page of what you heard.</p>"},{"title":"Weeks 3 to 6: set the rhythm","description":"<p>Weekly one-to-ones, one team meeting with a fixed agenda and clear owners for the work.</p>"},{"title":"Weeks 7 to 12: grow the team","description":"<p>First feedback both ways, one development goal per person and the <a href=\"/work/manager-conversation-guide/\">conversation before a resignation</a>, practised.</p>"}]}},{"id":"work-first-90-days-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/first-90-days/diagram.webp","alt_text":"Diagram in three stages: weeks one and two, listen and learn; weeks three to six, set the rhythm; weeks seven to twelve, grow the team.","caption":"The first 90 days in three stages."}},{"id":"work-first-90-days-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["The Grimoire and The Night School"],"body":"<p><a href=\"/services/manager-enablement\">The Grimoire</a> turns this plan into a kit with your company''s tools and tone, from €900. <a href=\"/services/manager-enablement\">The Night School</a> keeps the habits going with a monthly clinic, from €400 a month.</p><p>It borrows from the <a href=\"/work/onboarding-buddy-programme/\">onboarding programme</a> Robert built for around 300 new hires.</p>"}},{"id":"work-first-90-days-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What should a new manager do in the first 90 days?","answer":"<p>Listen in weeks one and two, set the team''s rhythm in weeks three to six and grow the team in weeks seven to twelve.</p>"},{"question":"How much do The Grimoire and The Night School cost?","answer":"<p>The Grimoire is from €900. The Night School is from €400 a month.</p>"}]}}]'::jsonb,
  '[{"id":"work-first-90-days-1","type":"text","strip_title":"The scenario","bg_color":"","layout":{},"content":{"eyebrow":"The scenario","title_lines":["Promoted on Friday, managing on Monday"],"body":"<p>Most new managers are promoted for being good at the job they just left. The first 90 days decide whether the team gets a manager or a very busy colleague.</p>"}},{"id":"work-first-90-days-2","type":"process_steps","strip_title":"The plan","bg_color":"","layout":{},"content":{"eyebrow":"The plan","title_lines":["Three stages"],"steps":[{"title":"Weeks 1 and 2: listen","description":"<p>A one-to-one with everyone, the same five questions each time, and a page of what you heard.</p>"},{"title":"Weeks 3 to 6: set the rhythm","description":"<p>Weekly one-to-ones, one team meeting with a fixed agenda and clear owners for the work.</p>"},{"title":"Weeks 7 to 12: grow the team","description":"<p>First feedback both ways, one development goal per person and the <a href=\"/work/manager-conversation-guide/\">conversation before a resignation</a>, practised.</p>"}]}},{"id":"work-first-90-days-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/first-90-days/diagram.webp","alt_text":"Diagram in three stages: weeks one and two, listen and learn; weeks three to six, set the rhythm; weeks seven to twelve, grow the team.","caption":"The first 90 days in three stages."}},{"id":"work-first-90-days-4","type":"text","strip_title":"Where it fits","bg_color":"","layout":{},"content":{"eyebrow":"Where it fits","title_lines":["The Grimoire and The Night School"],"body":"<p><a href=\"/services/manager-enablement\">The Grimoire</a> turns this plan into a kit with your company''s tools and tone, from €900. <a href=\"/services/manager-enablement\">The Night School</a> keeps the habits going with a monthly clinic, from €400 a month.</p><p>It borrows from the <a href=\"/work/onboarding-buddy-programme/\">onboarding programme</a> Robert built for around 300 new hires.</p>"}},{"id":"work-first-90-days-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"What should a new manager do in the first 90 days?","answer":"<p>Listen in weeks one and two, set the team''s rhythm in weeks three to six and grow the team in weeks seven to twelve.</p>"},{"question":"How much do The Grimoire and The Night School cost?","answer":"<p>The Grimoire is from €900. The Night School is from €400 a month.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  true,
  200,
  'draft',
  'A new manager''s first 90 days: a playbook',
  'A first-time manager''s 90-day plan in three stages: listen, set the rhythm, then grow the team. From The Grimoire and The Night School.',
  '/work/first-90-days/og.jpg',
  'Playbook, illustrative example, not client work. A 90-day plan for first-time managers in three stages: weeks one and two (listen and learn), weeks three to six (set the rhythm) and weeks seven to twelve (grow the team). It is built from The Magic Coffin''s manager starter kit, The Grimoire (from €900), and the monthly clinic, The Night School (from €400 a month).')
