-- 21 A two-week curriculum for support agents
INSERT INTO public.work_items (slug, type, pillar, title, summary, metric, metric_label, proof_point_id, card_style, pull_line, honesty_label, role_title, year, tags, cover_image, cover_image_alt, link_out, has_case_study, case_rows, draft_case_rows, case_proof_ids, featured_home, sort_order, status, meta_title, meta_description, og_image, ai_summary)
VALUES ('support-onboarding-curriculum',
  'case',
  'mgr',
  'A two-week curriculum for support agents',
  'A two-week onboarding curriculum for about 30 customer support agents at a European fintech, with coaching built on quality audits.',
  '',
  '',
  NULL,
  'photo',
  'Coach the skill the audit shows is missing.',
  'Real work, anonymised',
  'Quality Process Analyst and Training Specialist',
  '2021 to 2022',
  ARRAY['Training design', 'Coaching', 'Customer support', 'Quality']::text[],
  '/work/support-onboarding-curriculum/cover.webp',
  'A person in silhouette walking through a dark office.',
  '',
  true,
  '[{"id":"work-support-onboarding-curriculum-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["New agents learning on live customers"],"body":"<p>A UK support team at a European fintech needed new agents to investigate cases well and treat customers with care from week one. Coaching happened when someone had time.</p>"}},{"id":"work-support-onboarding-curriculum-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Curriculum first, then coaching from the data"],"steps":[{"title":"Wrote the curriculum","description":"<p>A two-week onboarding programme for each new cohort, on investigation skills and customer empathy.</p>"},{"title":"Audited the work","description":"<p>He ran quality audits in Freshdesk Quality.</p>"},{"title":"Found the gaps","description":"<p>He used QlikSense and Splunk to see which skills were missing, and where.</p>"},{"title":"Coached one to one","description":"<p>Each of about 30 agents got coaching on what their audits showed.</p>"},{"title":"Changed the process","description":"<p>He pushed a change to the write-off routine, so agents could settle more standard cases without waiting for a manager.</p>"}]}},{"id":"work-support-onboarding-curriculum-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/support-onboarding-curriculum/diagram.webp","alt_text":"Diagram in five steps: a two-week curriculum on investigation and empathy, quality audits in Freshdesk Quality, finding gaps in QlikSense and Splunk, one-to-one coaching, and a change to the write-off routine.","caption":"From the curriculum to audit-led coaching."}},{"id":"work-support-onboarding-curriculum-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Better calls, fewer bottlenecks"],"body":"<p>Customer satisfaction went up with agents'' professionalism and empathy (no exact figure is on record, so none is shown here). Fewer standard cases waited for a manager. Robert was promoted to Business Operations Associate on the strength of this work.</p><p>The same habit of building, then measuring, then coaching runs through the <a href=\"/work/mandatory-training/\">mandatory training</a> and the <a href=\"/work/first-90-days/\">first 90 days</a> plan for managers.</p>"}},{"id":"work-support-onboarding-curriculum-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How long should onboarding for support agents be?","answer":"<p>Here it was a two-week curriculum per cohort, followed by coaching from quality audits.</p>"},{"question":"Which tools did the coaching use?","answer":"<p>Freshdesk Quality for audits, and QlikSense and Splunk to find skill gaps.</p>"}]}}]'::jsonb,
  '[{"id":"work-support-onboarding-curriculum-1","type":"text","strip_title":"The problem","bg_color":"","layout":{},"content":{"eyebrow":"The problem","title_lines":["New agents learning on live customers"],"body":"<p>A UK support team at a European fintech needed new agents to investigate cases well and treat customers with care from week one. Coaching happened when someone had time.</p>"}},{"id":"work-support-onboarding-curriculum-2","type":"process_steps","strip_title":"What Robert did","bg_color":"","layout":{},"content":{"eyebrow":"What Robert did","title_lines":["Curriculum first, then coaching from the data"],"steps":[{"title":"Wrote the curriculum","description":"<p>A two-week onboarding programme for each new cohort, on investigation skills and customer empathy.</p>"},{"title":"Audited the work","description":"<p>He ran quality audits in Freshdesk Quality.</p>"},{"title":"Found the gaps","description":"<p>He used QlikSense and Splunk to see which skills were missing, and where.</p>"},{"title":"Coached one to one","description":"<p>Each of about 30 agents got coaching on what their audits showed.</p>"},{"title":"Changed the process","description":"<p>He pushed a change to the write-off routine, so agents could settle more standard cases without waiting for a manager.</p>"}]}},{"id":"work-support-onboarding-curriculum-3","type":"image","strip_title":"Diagram","bg_color":"","layout":{},"content":{"url":"/work/support-onboarding-curriculum/diagram.webp","alt_text":"Diagram in five steps: a two-week curriculum on investigation and empathy, quality audits in Freshdesk Quality, finding gaps in QlikSense and Splunk, one-to-one coaching, and a change to the write-off routine.","caption":"From the curriculum to audit-led coaching."}},{"id":"work-support-onboarding-curriculum-4","type":"text","strip_title":"What changed","bg_color":"","layout":{},"content":{"eyebrow":"What changed","title_lines":["Better calls, fewer bottlenecks"],"body":"<p>Customer satisfaction went up with agents'' professionalism and empathy (no exact figure is on record, so none is shown here). Fewer standard cases waited for a manager. Robert was promoted to Business Operations Associate on the strength of this work.</p><p>The same habit of building, then measuring, then coaching runs through the <a href=\"/work/mandatory-training/\">mandatory training</a> and the <a href=\"/work/first-90-days/\">first 90 days</a> plan for managers.</p>"}},{"id":"work-support-onboarding-curriculum-faq","type":"faq","strip_title":"Questions","bg_color":"","layout":{},"content":{"eyebrow":"Questions people ask","title_lines":["Quick answers"],"items":[{"question":"How long should onboarding for support agents be?","answer":"<p>Here it was a two-week curriculum per cohort, followed by coaching from quality audits.</p>"},{"question":"Which tools did the coaching use?","answer":"<p>Freshdesk Quality for audits, and QlikSense and Splunk to find skill gaps.</p>"}]}}]'::jsonb,
  '{}'::uuid[],
  false,
  210,
  'draft',
  'Two-week support agent onboarding curriculum',
  'How a two-week curriculum and audit-led coaching trained about 30 support agents at a European fintech, using Freshdesk Quality, QlikSense and Splunk.',
  '/work/support-onboarding-curriculum/og.jpg',
  'Case study. As Quality Process Analyst and Training Specialist at a European fintech (2021 to 2022), Robert-Marian Stănescu designed a two-week onboarding curriculum for new support cohorts on investigation skills and customer empathy, and coached about 30 agents one to one from quality audits in Freshdesk Quality, QlikSense and Splunk. The work also changed a write-off routine so agents could settle more standard cases without a manager''s sign-off.')
